import { Q, W, indexBy } from './_helper.js';

const M = (n, title, qs, opts) => W('H10TA', 'tieng-anh', n, title, qs, opts);

export const H10TA_WEEKS = [
  // ──────────────── HK1 ────────────────
  M(1, 'Unit 1 — Family Life · Vocabulary', [
    Q('"Household chores" có nghĩa là?', ['Người thân', 'Bài tập về nhà', 'Việc nhà', 'Tiền tiêu'], 2, 'Household chores = công việc gia đình.', ['Sai — "người thân" là relatives/family members, không phải household chores.', 'Sai — "bài tập về nhà" là homework, dễ nhầm vì cùng có chữ "nhà".', 'Đúng — household chores = việc nhà (chores = công việc lặt vặt trong nhà).', 'Sai — "tiền tiêu" là allowance/pocket money, không liên quan.']),
    Q('"Breadwinner" trong gia đình là?', ['Hàng xóm', 'Người con', 'Người kiếm tiền chính', 'Người nội trợ'], 2, 'Breadwinner = trụ cột tài chính.', ['Sai — "hàng xóm" là neighbour, không phải breadwinner.', 'Sai — "người con" là child, không phải trụ cột kinh tế.', 'Đúng — breadwinner = người kiếm tiền chính nuôi cả nhà.', 'Sai — "người nội trợ" là homemaker/housewife, ngược với breadwinner.']),
    Q('"To do the laundry" nghĩa là?', ['Giặt giũ', 'Quét nhà', 'Nấu cơm', 'Rửa bát'], 0, 'Laundry = đồ giặt.', ['Đúng — do the laundry = giặt giũ (laundry = đồ cần giặt).', 'Sai — "quét nhà" là sweep the floor, khác collocation.', 'Sai — "nấu cơm" là cook/do the cooking, không phải laundry.', 'Sai — "rửa bát" là do the dishes, dễ nhầm vì cùng "do the...".']),
    Q('"Nuclear family" gồm?', ['Họ hàng xa', 'Cha mẹ và con cái', 'Một mình', 'Đại gia đình 3 thế hệ'], 1, 'Nuclear = gia đình hạt nhân nhỏ.', ['Sai — "họ hàng xa" là distant relatives, đó là extended family.', 'Đúng — nuclear family = gia đình hạt nhân (chỉ cha mẹ và con cái).', 'Sai — "một mình" không phải một family, sai khái niệm.', 'Sai — "đại gia đình 3 thế hệ" là extended family, ngược nghĩa.']),
    Q('"Extended family" là?', ['Đại gia đình nhiều thế hệ', 'Bạn thân', 'Gia đình ly tán', 'Một mình'], 0, 'Extended family = đại gia đình.', ['Đúng — extended family = đại gia đình nhiều thế hệ, có cả ông bà, cô dì.', 'Sai — "bạn thân" là close friends, không phải gia đình.', 'Sai — "gia đình ly tán" là broken family, sai nghĩa.', 'Sai — "một mình" không phải family, sai khái niệm.']),
    Q('Chọn từ phù hợp: "She always ___ the dishes after dinner."', ['does', 'washes (rửa - dễ chọn sai vì cùng nghĩa rửa)', 'makes (làm - lẫn với make dinner)', 'takes (cầm - nhầm collocation)'], 0, 'Collocation: do the dishes (rửa bát).', ['Đúng — collocation chuẩn là "do the dishes" (rửa bát).', 'Sai — "washes" cũng nghĩa rửa nhưng không phải collocation cố định "do the dishes".', 'Sai — "makes" đi với make dinner, không dùng make the dishes.', 'Sai — "takes" sai collocation hoàn toàn với the dishes.']),
  ]),

  M(2, 'Unit 1 — Family Life · Present simple vs Present continuous', [
    Q('"My mother ___ dinner every evening." Chọn?', ['cooks', 'cooked', 'is cook (sai dạng động từ)', 'is cooking'], 0, '"Every evening" → present simple.', ['Đúng — "every evening" là dấu hiệu hiện tại đơn → cooks.', 'Sai — "cooked" là quá khứ đơn, không hợp dấu hiệu thói quen "every evening".', 'Sai — "is cook" sai dạng: sau is phải là V-ing (is cooking).', 'Sai — "is cooking" là hiện tại tiếp diễn, không hợp thói quen lặp lại.']),
    Q('"Look! The baby ___."', ['cried (quá khứ - sai vì Look! ở hiện tại)', 'cries (HTĐ - chỉ thói quen, không hợp \'Look!\')', 'cry (V nguyên - thiếu trợ động từ)', 'is crying'], 3, '"Look!" → đang xảy ra → continuous.', ['Sai — "cried" là quá khứ, mâu thuẫn với "Look!" chỉ hiện tại.', 'Sai — "cries" là hiện tại đơn (thói quen), không hợp "Look!".', 'Sai — "cry" thiếu trợ động từ be, sai cấu trúc tiếp diễn.', 'Đúng — "Look!" báo việc đang diễn ra → hiện tại tiếp diễn is crying.']),
    Q('"He always ___ his bike to school."', ['rides', 'rode (quá khứ - không hợp \'always\')', 'ride (sai chia ngôi 3 số ít)', 'is riding'], 0, 'Thói quen → simple.', ['Đúng — "always" là trạng từ tần suất → hiện tại đơn rides.', 'Sai — "rode" là quá khứ đơn, không hợp "always" (thói quen).', 'Sai — "ride" thiếu -s cho ngôi 3 số ít (he).', 'Sai — "is riding" là tiếp diễn, không hợp thói quen với "always".']),
    Q('"I ___ TV at the moment."', ['watched', 'watch (V nguyên - thiếu trợ động từ be)', 'am watching', 'watches'], 2, '"At the moment" → continuous.', ['Sai — "watched" là quá khứ, mâu thuẫn "at the moment" (hiện tại).', 'Sai — "watch" thiếu trợ động từ am, sai cấu trúc tiếp diễn.', 'Đúng — "at the moment" → hiện tại tiếp diễn am watching.', 'Sai — "watches" là hiện tại đơn ngôi 3, không hợp với I.']),
    Q('Dấu hiệu của present simple?', ['now, at the moment', 'last week, ago', 'since, for', 'always, usually, often'], 3, 'Trạng từ tần suất.', ['Sai — "now, at the moment" là dấu hiệu hiện tại tiếp diễn.', 'Sai — "last week, ago" là dấu hiệu quá khứ đơn.', 'Sai — "since, for" là dấu hiệu hiện tại hoàn thành.', 'Đúng — always, usually, often là trạng từ tần suất của hiện tại đơn.']),
    Q('Chia: "She ___ (study) every night."', ['studies', 'study (sai chia ngôi 3 số ít)', 'studied', 'is studying'], 0, 'Ngôi 3 số ít + study → studies.', ['Đúng — ngôi 3 số ít + study → đổi y thành ies = studies.', 'Sai — "study" thiếu -es cho ngôi 3 số ít (she).', 'Sai — "studied" là quá khứ, không hợp "every night" (thói quen).', 'Sai — "is studying" là tiếp diễn, không hợp thói quen lặp lại.']),
  ]),

  M(3, 'Unit 2 — Humans and the Environment · Vocabulary', [
    Q('"Pollution" nghĩa là?', ['Ô nhiễm', 'Năng lượng', 'Khí hậu', 'Bảo tồn'], 0, 'Pollution = sự ô nhiễm.', ['Đúng — pollution = sự ô nhiễm.', 'Sai — "năng lượng" là energy, không phải pollution.', 'Sai — "khí hậu" là climate, dễ nhầm vì cùng chủ đề môi trường.', 'Sai — "bảo tồn" là conservation, ngược nghĩa với ô nhiễm.']),
    Q('"Deforestation" là?', ['Cháy rừng', 'Phá rừng', 'Khu bảo tồn', 'Trồng rừng'], 1, 'Deforestation = sự phá rừng.', ['Sai — "cháy rừng" là forest fire, không phải deforestation.', 'Đúng — deforestation = sự phá rừng (de- = bỏ, forest = rừng).', 'Sai — "khu bảo tồn" là reserve, sai nghĩa.', 'Sai — "trồng rừng" là afforestation, ngược nghĩa với phá rừng.']),
    Q('"To recycle" nghĩa là?', ['Mua mới', 'Tái chế', 'Vứt bỏ', 'Tái sử dụng'], 1, 'Recycle = tái chế.', ['Sai — "mua mới" là buy new, không phải recycle.', 'Đúng — recycle = tái chế (xử lý rác thành sản phẩm mới).', 'Sai — "vứt bỏ" là throw away, ngược nghĩa.', 'Sai — "tái sử dụng" là reuse, khái niệm gần nhưng khác recycle.']),
    Q('"Carbon footprint" là?', ['Dấu chân carbon (lượng khí thải)', 'Đầm lầy', 'Vết chân lớn', 'Chân ghế'], 0, 'Carbon footprint = chỉ số CO₂ phát thải.', ['Đúng — carbon footprint = dấu chân carbon, lượng khí thải CO₂ gây ra.', 'Sai — "đầm lầy" là swamp/marsh, không liên quan.', 'Sai — "vết chân lớn" là nghĩa đen, không phải thuật ngữ môi trường.', 'Sai — "chân ghế" sai hoàn toàn, không phải nghĩa.']),
    Q('"Endangered species" nghĩa là?', ['Loài thường', 'Loài mới', 'Loài có nguy cơ tuyệt chủng', 'Loài quý hiếm bình thường'], 2, 'Endangered = đang bị đe doạ.', ['Sai — "loài thường" là common species, ngược nghĩa.', 'Sai — "loài mới" là new species, không phải endangered.', 'Đúng — endangered species = loài có nguy cơ tuyệt chủng.', 'Sai — "loài quý hiếm bình thường" là rare species, chưa tới mức nguy cấp.']),
    Q('Hành động bảo vệ môi trường: ___ plastic bags.', ['buy more (mua thêm - ngược với bảo vệ môi trường)', 'produce (sản xuất - làm tăng rác nhựa)', 'increase', 'reduce'], 3, 'Reduce, reuse, recycle — 3Rs.', ['Sai — "buy more" (mua thêm) ngược với bảo vệ môi trường.', 'Sai — "produce" (sản xuất) làm tăng rác nhựa, sai mục tiêu.', 'Sai — "increase" (tăng) ngược với giảm rác thải.', 'Đúng — reduce = giảm, thuộc nguyên tắc 3Rs (reduce, reuse, recycle).']),
  ]),

  M(4, 'Unit 2 — Humans and the Environment · Comparative & Superlative', [
    Q('"This city is ___ than the other."', ['most polluted', 'more polluted', 'pollute', 'polluteder'], 1, 'Tính từ dài: more + adj + than.', ['Sai — "most polluted" là so sánh nhất, không đi với "than".', 'Đúng — tính từ dài → more + adj + than (more polluted than).', 'Sai — "pollute" là động từ, không phải tính từ so sánh.', 'Sai — "polluteder" sai: tính từ dài không thêm -er.']),
    Q('"The Amazon is ___ rainforest in the world."', ['more large', 'the largest', 'largest (thiếu mạo từ \'the\' trước so sánh nhất)', 'larger'], 1, 'So sánh nhất: the largest.', ['Sai — "more large" sai: large là adj ngắn, dùng larger không phải more large.', 'Đúng — so sánh nhất adj ngắn: the + adj-est = the largest.', 'Sai — "largest" thiếu mạo từ "the" trước so sánh nhất.', 'Sai — "larger" là so sánh hơn, không hợp "in the world" (nhất).']),
    Q('"Climate change is getting ___ ___."', ['more bad', 'bad and bad', 'baddest', 'worse and worse'], 3, 'Cấu trúc tăng tiến: comparative + and + comparative.', ['Sai — "more bad" sai: bad là bất quy tắc → worse, không more bad.', 'Sai — "bad and bad" sai cấu trúc tăng tiến, phải dùng so sánh hơn.', 'Sai — "baddest" sai: bad bất quy tắc → worst.', 'Đúng — cấu trúc tăng tiến: comparative + and + comparative = worse and worse.']),
    Q('"This air is ___ than yesterday."', ['cleanest', 'cleaner', 'more clean', 'more cleaner (sai - kép hai dạng so sánh)'], 1, 'Adj ngắn 1 âm: + er.', ['Sai — "cleanest" là so sánh nhất, không đi với "than".', 'Đúng — adj ngắn 1 âm tiết + er = cleaner than.', 'Sai — "more clean" sai: clean là adj ngắn, dùng cleaner.', 'Sai — "more cleaner" lỗi kép, không gộp more với -er.']),
    Q('"The more trees we plant, the ___ air we have."', ['the cleaner (thừa \'the\' trong vế thứ hai)', 'cleanest', 'more clean', 'cleaner'], 3, 'Cấu trúc "the + comparative, the + comparative".', ['Sai — vế hai "the cleaner" thừa "the" nếu đứng riêng; ở đây cần dạng "the cleaner" nhưng phương án này gắn chú thích thừa "the".', 'Sai — "cleanest" là so sánh nhất, không hợp cấu trúc "the + comparative".', 'Sai — "more clean" sai dạng: clean dùng cleaner.', 'Đúng — cấu trúc "the + comparative, the + comparative" → the cleaner.']),
    Q('"Recycling is ___ than burning waste."', ['the better (thừa \'the\' - đây là so sánh hơn)', 'better', 'more good (sai - good là tính từ bất quy tắc)', 'gooder'], 1, 'Good → better → the best.', ['Sai — "the better" thừa "the": đây là so sánh hơn với "than".', 'Đúng — good là bất quy tắc → better than.', 'Sai — "more good" sai: good bất quy tắc → better, không more good.', 'Sai — "gooder" sai: good bất quy tắc → better.']),
  ]),

  M(5, 'Unit 3 — Music · Vocabulary', [
    Q('"Composer" nghĩa là?', ['Người sáng tác nhạc', 'Nhạc cụ', 'Khán giả', 'Nhạc trưởng (conductor - hay nhầm với composer)'], 0, 'Composer = nhà soạn nhạc.', ['Đúng — composer = nhà soạn nhạc/người sáng tác nhạc.', 'Sai — "nhạc cụ" là instrument, không phải người.', 'Sai — "khán giả" là audience, sai nghĩa.', 'Sai — "nhạc trưởng" là conductor, dễ nhầm nhưng khác composer.']),
    Q('"Lyrics" là?', ['Tuyển tập bài hát (album - dễ nhầm khái niệm)', 'Giai điệu', 'Nhạc cụ', 'Lời bài hát'], 3, 'Lyrics = lời ca khúc.', ['Sai — "tuyển tập bài hát" là album, dễ nhầm khái niệm.', 'Sai — "giai điệu" là melody, không phải lyrics.', 'Sai — "nhạc cụ" là instrument, sai nghĩa.', 'Đúng — lyrics = lời bài hát.']),
    Q('"To release an album" nghĩa là?', ['Mua album', 'Sửa album', 'Nghe album', 'Phát hành album'], 3, 'Release = phát hành.', ['Sai — "mua album" là buy, không phải release.', 'Sai — "sửa album" là edit, sai nghĩa.', 'Sai — "nghe album" là listen to, không phải release.', 'Đúng — release = phát hành (đưa album ra công chúng).']),
    Q('"Concert" là?', ['Ban nhạc', 'Phòng thu', 'Bài hát', 'Buổi hoà nhạc'], 3, 'Concert = buổi biểu diễn nhạc.', ['Sai — "ban nhạc" là band, không phải concert.', 'Sai — "phòng thu" là studio, sai nghĩa.', 'Sai — "bài hát" là song, không phải buổi diễn.', 'Đúng — concert = buổi hoà nhạc/biểu diễn.']),
    Q('"Audience" nghĩa là?', ['Đạo diễn', 'Diễn viên', 'Nhạc cụ', 'Khán giả'], 3, 'Audience = người xem/nghe.', ['Sai — "đạo diễn" là director, sai nghĩa.', 'Sai — "diễn viên" là actor, không phải khán giả.', 'Sai — "nhạc cụ" là instrument, sai nghĩa.', 'Đúng — audience = khán giả (người xem/nghe).']),
    Q('Thể loại nào KHÔNG phải genre nhạc?', ['Jazz (là thể loại nhạc, đáp án này SAI nhãn)', 'Rock (là thể loại nhạc, đáp án này SAI nhãn)', 'Cinema', 'Pop (là thể loại nhạc, đáp án này SAI nhãn)'], 2, 'Cinema là điện ảnh, không phải thể loại nhạc.', ['Sai — Jazz là một thể loại nhạc, nên đây không phải đáp án.', 'Sai — Rock là một thể loại nhạc, nên đây không phải đáp án.', 'Đúng — Cinema là điện ảnh, không phải thể loại nhạc.', 'Sai — Pop là một thể loại nhạc, nên đây không phải đáp án.']),
  ]),

  M(6, 'Unit 3 — Music · Past Simple vs Past Continuous', [
    Q('"I ___ TV when she called me."', ['am watching', 'watch (V nguyên - thiếu trợ động từ was)', 'watched', 'was watching'], 3, 'Hành động đang xảy ra (continuous) bị cắt ngang (simple).', ['Sai — "am watching" là hiện tại, mâu thuẫn "when she called" (quá khứ).', 'Sai — "watch" thiếu trợ động từ was, sai cấu trúc.', 'Sai — "watched" là quá khứ đơn, không nhấn việc đang diễn ra bị cắt ngang.', 'Đúng — hành động đang diễn ra (was watching) bị hành động khác (called) cắt ngang.']),
    Q('"She ___ to Hanoi last summer."', ['has gone', 'goes (HTĐ - không hợp với \'last summer\')', 'was going', 'went'], 3, '"Last summer" → past simple.', ['Sai — "has gone" là hiện tại hoàn thành, không đi với "last summer".', 'Sai — "goes" là hiện tại đơn, không hợp "last summer".', 'Sai — "was going" tiếp diễn, không nhấn sự kiện đã hoàn tất.', 'Đúng — "last summer" là mốc quá khứ rõ → quá khứ đơn went.']),
    Q('"While I ___ dinner, the phone rang."', ['cook (V nguyên - thiếu trợ động từ was)', 'was cooking', 'is cooking', 'cooked'], 1, 'Hành động kéo dài trong quá khứ → continuous.', ['Sai — "cook" thiếu trợ động từ was, sai cấu trúc tiếp diễn.', 'Đúng — "While + hành động kéo dài" trong quá khứ → was cooking.', 'Sai — "is cooking" là hiện tại, mâu thuẫn "rang" (quá khứ).', 'Sai — "cooked" là quá khứ đơn, không diễn tả hành động đang kéo dài.']),
    Q('"They ___ at the concert last night."', ['sing (V nguyên - không hợp \'last night\')', 'sang (QKĐ - không nhấn mạnh đang diễn ra)', 'are singing', 'were singing'], 3, '"Last night" + đang diễn ra → continuous.', ['Sai — "sing" thiếu trợ động từ were, sai cấu trúc.', 'Sai — "sang" quá khứ đơn, không nhấn đang diễn ra tại thời điểm đó.', 'Sai — "are singing" là hiện tại, mâu thuẫn "last night".', 'Đúng — "last night" + nhấn đang diễn ra → quá khứ tiếp diễn were singing.']),
    Q('Dạng quá khứ của "buy"?', ['buyed (sai - buy là bất quy tắc, không +ed)', 'bought', 'buys (HTĐ ngôi 3 - không phải quá khứ)', 'buying'], 1, 'Bất quy tắc: buy → bought.', ['Sai — "buyed" sai: buy là bất quy tắc, không thêm -ed.', 'Đúng — buy là bất quy tắc → bought.', 'Sai — "buys" là hiện tại đơn ngôi 3, không phải quá khứ.', 'Sai — "buying" là V-ing, không phải dạng quá khứ.']),
    Q('Dạng quá khứ của "sing"?', ['sang', 'sings (HTĐ ngôi 3 - không phải quá khứ)', 'singed', 'sung (là V3 - không dùng cho quá khứ đơn)'], 0, 'Sing → sang → sung.', ['Đúng — sing là bất quy tắc → sang (V2).', 'Sai — "sings" là hiện tại đơn ngôi 3, không phải quá khứ.', 'Sai — "singed" sai: sing là bất quy tắc, không thêm -ed.', 'Sai — "sung" là V3 (quá khứ phân từ), không dùng cho quá khứ đơn.']),
  ]),

  M(7, 'Unit 4 — For a Better Community · Vocabulary', [
    Q('"Volunteer" nghĩa là?', ['Học sinh', 'Tình nguyện viên', 'Du khách (tourist - dễ nhầm với volunteer)', 'Giáo viên'], 1, 'Volunteer = người tình nguyện.', ['Sai — "học sinh" là student, không phải volunteer.', 'Đúng — volunteer = tình nguyện viên.', 'Sai — "du khách" là tourist, dễ nhầm âm nhưng khác nghĩa.', 'Sai — "giáo viên" là teacher, sai nghĩa.']),
    Q('"Charity" là?', ['Trường học', 'Tổ chức từ thiện', 'Công ty', 'Bệnh viện'], 1, 'Charity = từ thiện.', ['Sai — "trường học" là school, không phải charity.', 'Đúng — charity = tổ chức/hoạt động từ thiện.', 'Sai — "công ty" là company, sai nghĩa.', 'Sai — "bệnh viện" là hospital, không phải charity.']),
    Q('"Donate" nghĩa là?', ['Quyên góp', 'Mua hàng (purchase - ngược nghĩa)', 'Bán hàng (sell - khác hoàn toàn)', 'Vay mượn (borrow - dễ nhầm vì cùng giao dịch)'], 0, 'Donate = cho/quyên góp.', ['Đúng — donate = quyên góp/cho (tiền, đồ vật).', 'Sai — "mua hàng" là purchase, ngược nghĩa với cho đi.', 'Sai — "bán hàng" là sell, khác hoàn toàn.', 'Sai — "vay mượn" là borrow, dễ nhầm vì cùng giao dịch nhưng ngược chiều.']),
    Q('"Community service" là?', ['Dịch vụ khách hàng', 'Dịch vụ trả phí', 'Phục vụ cộng đồng', 'Hỗ trợ kỹ thuật'], 2, 'Hoạt động cộng đồng.', ['Sai — "dịch vụ khách hàng" là customer service, sai nghĩa.', 'Sai — "dịch vụ trả phí" là paid service, không phải cộng đồng.', 'Đúng — community service = hoạt động phục vụ cộng đồng.', 'Sai — "hỗ trợ kỹ thuật" là technical support, sai nghĩa.']),
    Q('"Disadvantaged children" là?', ['Trẻ em mới sinh', 'Trẻ em chăm', 'Trẻ em giàu', 'Trẻ em kém may mắn'], 3, 'Disadvantaged = thiệt thòi.', ['Sai — "trẻ mới sinh" là newborn, sai nghĩa.', 'Sai — "trẻ chăm" là hard-working, không phải disadvantaged.', 'Sai — "trẻ giàu" là well-off, ngược nghĩa.', 'Đúng — disadvantaged children = trẻ em kém may mắn/thiệt thòi.']),
    Q('"Fundraising" nghĩa là?', ['Đầu tư', 'Tiết kiệm', 'Cho vay', 'Gây quỹ'], 3, 'Fundraising = hoạt động gây quỹ.', ['Sai — "đầu tư" là invest, sai nghĩa.', 'Sai — "tiết kiệm" là save, không phải fundraising.', 'Sai — "cho vay" là lend, sai nghĩa.', 'Đúng — fundraising = hoạt động gây quỹ.']),
  ]),

  M(8, 'Unit 4 — Past Simple & Present Perfect', [
    Q('"I ___ in Hanoi for 5 years."', ['lived (QKĐ - không diễn tả kéo dài tới hiện tại)', 'live (HTĐ - không có \'for 5 years\')', 'have lived', 'am living'], 2, 'Khoảng thời gian kéo dài đến hiện tại → present perfect.', ['Sai — "lived" quá khứ đơn, không diễn tả kéo dài tới hiện tại.', 'Sai — "live" hiện tại đơn, không hợp "for 5 years".', 'Đúng — "for + khoảng thời gian kéo dài tới hiện tại" → hiện tại hoàn thành have lived.', 'Sai — "am living" tiếp diễn, không nhấn quãng thời gian tích luỹ.']),
    Q('"She ___ to Paris last year."', ['went', 'has gone', 'goes (HTĐ ngôi 3 - không hợp \'last year\')', 'go (V nguyên - sai chia ngôi)'], 0, '"Last year" → past simple.', ['Đúng — "last year" là mốc quá khứ rõ → quá khứ đơn went.', 'Sai — "has gone" hiện tại hoàn thành, không đi với "last year".', 'Sai — "goes" hiện tại đơn ngôi 3, không hợp "last year".', 'Sai — "go" thiếu chia ngôi cho she, sai dạng.']),
    Q('Dấu hiệu của present perfect?', ['now, at the moment (dấu hiệu của HTTD)', 'ago, last', 'tomorrow', 'since, for, already, just, yet'], 3, 'Trạng từ đặc trưng PP.', ['Sai — "now, at the moment" là dấu hiệu hiện tại tiếp diễn.', 'Sai — "ago, last" là dấu hiệu quá khứ đơn.', 'Sai — "tomorrow" là dấu hiệu tương lai.', 'Đúng — since, for, already, just, yet là dấu hiệu hiện tại hoàn thành.']),
    Q('"I ___ ___ this book yet."', ['am not reading', 'haven\'t read', 'didn\'t read', 'don\'t read'], 1, '"Yet" trong câu phủ định → present perfect.', ['Sai — "am not reading" tiếp diễn, không hợp "yet".', 'Đúng — "yet" trong câu phủ định → hiện tại hoàn thành haven\'t read.', 'Sai — "didn\'t read" quá khứ đơn, "yet" thường đi với hiện tại hoàn thành.', 'Sai — "don\'t read" hiện tại đơn, không hợp "yet".']),
    Q('"He ___ to London twice."', ['was (QKĐ - không nói được \'twice\' tới giờ)', 'went (QKĐ - không diễn tả kinh nghiệm cuộc đời)', 'has been', 'goes (HTĐ - không phù hợp với \'twice\')'], 2, 'Kinh nghiệm cuộc đời → present perfect.', ['Sai — "was" quá khứ đơn, không diễn tả số lần tích luỹ tới hiện tại.', 'Sai — "went" quá khứ đơn, không nhấn kinh nghiệm tới giờ.', 'Đúng — "twice" (kinh nghiệm tới hiện tại) → has been.', 'Sai — "goes" hiện tại đơn, không phù hợp với "twice" (kinh nghiệm).']),
    Q('Quá khứ phân từ của "see"?', ['seen', 'saw (là quá khứ đơn V2, không phải V3)', 'sees (HTĐ ngôi 3 - không phải V3)', 'seeing'], 0, 'See → saw → seen.', ['Đúng — see → saw → seen; quá khứ phân từ là seen.', 'Sai — "saw" là quá khứ đơn (V2), không phải V3.', 'Sai — "sees" là hiện tại đơn ngôi 3, không phải V3.', 'Sai — "seeing" là V-ing, không phải quá khứ phân từ.']),
  ]),

  M(9, 'Unit 5 — Inventions · Vocabulary', [
    Q('"Invention" nghĩa là?', ['Bản quyền', 'Phát minh', 'Sản phẩm', 'Khám phá'], 1, 'Invention = phát minh.', ['Sai — "bản quyền" là copyright, sai nghĩa.', 'Đúng — invention = phát minh.', 'Sai — "sản phẩm" là product, không phải invention.', 'Sai — "khám phá" là discovery, dễ nhầm nhưng khác (tìm cái sẵn có).']),
    Q('"Innovate" là?', ['Đổi mới', 'Sao chép', 'Phát minh (invent - nghĩa gần nhưng khác)', 'Sửa chữa'], 0, 'Innovate = cách tân.', ['Đúng — innovate = đổi mới/cách tân.', 'Sai — "sao chép" là copy, ngược nghĩa.', 'Sai — "phát minh" là invent, nghĩa gần nhưng khác innovate.', 'Sai — "sửa chữa" là repair, sai nghĩa.']),
    Q('Phân biệt "invent" và "discover"?', ['Không liên quan', 'Invent: tạo cái mới; Discover: tìm ra cái sẵn có', 'Ngược lại nghĩa', 'Như nhau'], 1, 'Invent = sáng chế, Discover = phát hiện.', ['Sai — invent và discover có liên quan đến tạo/tìm cái mới.', 'Đúng — invent = tạo ra cái mới; discover = tìm ra cái đã có sẵn.', 'Sai — không phải ngược nghĩa hoàn toàn, mà khác bản chất.', 'Sai — không phải như nhau: invent là sáng chế, discover là phát hiện.']),
    Q('"Patent" là?', ['Giấy phép kinh doanh (license - dễ nhầm với patent)', 'Bằng tốt nghiệp', 'Bằng sáng chế', 'Bằng lái'], 2, 'Patent = quyền sở hữu phát minh.', ['Sai — "giấy phép kinh doanh" là business license, dễ nhầm nhưng khác.', 'Sai — "bằng tốt nghiệp" là diploma, sai nghĩa.', 'Đúng — patent = bằng sáng chế (quyền sở hữu phát minh).', 'Sai — "bằng lái" là driving licence, sai nghĩa.']),
    Q('"Smartphone" được phát minh dựa trên?', ['Phone + computer', 'TV + internet (sai - không phải bản chất)', 'Computer', 'Phone + camera (camera chỉ là phụ kiện)'], 0, 'Smartphone kết hợp điện thoại và máy tính.', ['Đúng — smartphone kết hợp điện thoại (phone) và máy tính (computer).', 'Sai — TV + internet không phải bản chất cấu thành smartphone.', 'Sai — chỉ "computer" là thiếu chức năng gọi điện cốt lõi.', 'Sai — camera chỉ là phụ kiện, không phải thành phần cốt lõi.']),
    Q('"Artificial Intelligence" (AI) là?', ['Trí tuệ nhân tạo', 'Trí tuệ tự nhiên', 'Người máy có cảm xúc (sai - đây chỉ là loại robot)', 'Mạng xã hội'], 0, 'AI = trí tuệ nhân tạo.', ['Đúng — Artificial Intelligence = trí tuệ nhân tạo.', 'Sai — "trí tuệ tự nhiên" là natural intelligence, ngược nghĩa.', 'Sai — robot có cảm xúc chỉ là một loại ứng dụng, không phải định nghĩa AI.', 'Sai — "mạng xã hội" là social network, sai nghĩa.']),
  ]),

  M(10, 'Unit 5 — Inventions · Passive Voice', [
    Q('"The telephone ___ by Bell."', ['invents', 'is inventing', 'invented', 'was invented'], 3, 'Bị động quá khứ: was + V3.', ['Sai — "invents" là hiện tại đơn chủ động, không phải bị động quá khứ.', 'Sai — "is inventing" tiếp diễn chủ động, sai dạng bị động.', 'Sai — "invented" thiếu trợ động từ was, đây là chủ động quá khứ.', 'Đúng — bị động quá khứ: was + V3 = was invented (by Bell).']),
    Q('"English ___ all over the world."', ['speaks', 'was spoken', 'is spoken', 'spoke (QKĐ chủ động - không phải bị động)'], 2, 'Bị động hiện tại: is/am/are + V3.', ['Sai — "speaks" hiện tại đơn chủ động, không phải bị động.', 'Sai — "was spoken" là quá khứ, không hợp sự thật hiện tại.', 'Đúng — bị động hiện tại: is/am/are + V3 = is spoken.', 'Sai — "spoke" quá khứ đơn chủ động, không phải bị động.']),
    Q('Đổi sang bị động: "They build a new school."', ['A new school has built.', 'A new school builds.', 'A new school is built (by them).', 'A new school was built.'], 2, 'Hiện tại đơn → is/am/are + V3.', ['Sai — "has built" sai dạng: bị động cần is built, không phải chủ động hoàn thành.', 'Sai — "builds" hiện tại đơn chủ động, không phải bị động.', 'Đúng — hiện tại đơn → bị động is/am/are + V3 = is built.', 'Sai — "was built" là quá khứ, câu gốc ở hiện tại (build).']),
    Q('"The Mona Lisa ___ by Leonardo da Vinci."', ['was painted', 'painted', 'paints', 'is painting'], 0, 'Bị động quá khứ.', ['Đúng — bị động quá khứ: was + V3 = was painted.', 'Sai — "painted" thiếu trợ động từ was, đây là chủ động quá khứ.', 'Sai — "paints" hiện tại đơn chủ động, sai thì và dạng.', 'Sai — "is painting" tiếp diễn chủ động, không phải bị động.']),
    Q('"This book ___ in 1990."', ['wrote (QKĐ chủ động - không phải bị động)', 'was written', 'writes', 'is written'], 1, 'Quá khứ bị động.', ['Sai — "wrote" quá khứ đơn chủ động, không phải bị động.', 'Đúng — quá khứ bị động: was + V3 = was written.', 'Sai — "writes" hiện tại đơn chủ động, sai thì.', 'Sai — "is written" là hiện tại, không hợp mốc "1990".']),
    Q('"Letters ___ by postmen every day."', ['delivered', 'is delivered', 'deliver', 'are delivered'], 3, 'Hiện tại bị động số nhiều.', ['Sai — "delivered" thiếu trợ động từ are, sai dạng bị động.', 'Sai — "is delivered" số ít, nhưng "Letters" số nhiều → are.', 'Sai — "deliver" là chủ động, không phải bị động.', 'Đúng — bị động hiện tại số nhiều: are + V3 = are delivered.']),
  ]),

  M(11, 'Unit 6 — Gender Equality · Vocabulary', [
    Q('"Gender equality" nghĩa là?', ['Bạo lực', 'Sự phân biệt', 'Bình đẳng giới', 'Hôn nhân'], 2, 'Gender equality = bình đẳng giới.', ['Sai — "bạo lực" là violence, sai nghĩa.', 'Sai — "sự phân biệt" là discrimination, ngược với bình đẳng.', 'Đúng — gender equality = bình đẳng giới.', 'Sai — "hôn nhân" là marriage, không liên quan.']),
    Q('"Discrimination" là?', ['Sự hợp tác', 'Sự phân biệt đối xử', 'Sự ủng hộ', 'Sự khen ngợi'], 1, 'Discrimination = phân biệt đối xử.', ['Sai — "sự hợp tác" là cooperation, ngược nghĩa.', 'Đúng — discrimination = sự phân biệt đối xử.', 'Sai — "sự ủng hộ" là support, sai nghĩa.', 'Sai — "sự khen ngợi" là praise, không phải discrimination.']),
    Q('"Stereotype" nghĩa là?', ['Định kiến', 'Tin tức', 'Sự thật', 'Sự kiện'], 0, 'Stereotype = khuôn mẫu, định kiến.', ['Đúng — stereotype = khuôn mẫu/định kiến.', 'Sai — "tin tức" là news, sai nghĩa.', 'Sai — "sự thật" là truth, ngược với định kiến.', 'Sai — "sự kiện" là event, không liên quan.']),
    Q('"Women\'s rights" là?', ['Quyền nam giới', 'Quyền trẻ em', 'Quyền chung', 'Quyền phụ nữ'], 3, 'Quyền của nữ giới.', ['Sai — "quyền nam giới" là men\'s rights, sai đối tượng.', 'Sai — "quyền trẻ em" là children\'s rights, sai đối tượng.', 'Sai — "quyền chung" là general rights, không cụ thể.', 'Đúng — women\'s rights = quyền phụ nữ.']),
    Q('"To empower women" nghĩa là?', ['Buộc phụ nữ', 'Trao quyền cho phụ nữ', 'Hạn chế phụ nữ', 'Bỏ quên phụ nữ'], 1, 'Empower = trao quyền, nâng cao vị thế.', ['Sai — "buộc phụ nữ" là force, ngược nghĩa.', 'Đúng — empower = trao quyền, nâng cao vị thế cho phụ nữ.', 'Sai — "hạn chế phụ nữ" là restrict, ngược nghĩa.', 'Sai — "bỏ quên phụ nữ" là neglect, sai nghĩa.']),
    Q('Câu nào thể hiện bình đẳng giới?', ['Women should stay home.', 'Only men can be leaders.', 'Both men and women have equal rights.', 'Boys are smarter than girls.'], 2, 'Thể hiện sự bình đẳng.', ['Sai — "Women should stay home" thể hiện định kiến giới, không bình đẳng.', 'Sai — "Only men can be leaders" phân biệt giới, không bình đẳng.', 'Đúng — "Both men and women have equal rights" thể hiện bình đẳng giới.', 'Sai — "Boys are smarter than girls" là định kiến, không bình đẳng.']),
  ]),

  M(12, 'Unit 6 — Modal Verbs (must, have to, should, ought to)', [
    Q('"You ___ wear a helmet when riding a motorbike." (bắt buộc theo luật)', ['must', 'can (có khả năng - không phải bắt buộc)', 'could (có thể - lời khuyên nhẹ, không phải luật)', 'may (có lẽ/được phép - không bắt buộc)'], 0, 'Must = bắt buộc.', ['Đúng — must = bắt buộc (theo luật phải đội mũ bảo hiểm).', 'Sai — "can" chỉ khả năng, không diễn tả bắt buộc.', 'Sai — "could" là lời khuyên nhẹ/khả năng quá khứ, không phải luật bắt buộc.', 'Sai — "may" chỉ sự cho phép/khả năng, không phải bắt buộc.']),
    Q('Phân biệt "must" và "have to"?', ['Ngược nghĩa', 'Không liên quan', 'Như nhau', 'Must: bắt buộc nội tại; Have to: bắt buộc ngoại tại'], 3, 'Must do bản thân thấy cần; have to do hoàn cảnh.', ['Sai — must và have to không ngược nghĩa, đều chỉ bắt buộc.', 'Sai — chúng có liên quan, đều diễn tả nghĩa vụ.', 'Sai — không hoàn toàn như nhau: khác ở nguồn của sự bắt buộc.', 'Đúng — must: bắt buộc do bản thân thấy cần; have to: bắt buộc do hoàn cảnh/quy định bên ngoài.']),
    Q('"You ___ smoke in the hospital." (cấm)', ['mustn\'t', 'shouldn\'t', 'can\'t (không thể - chỉ khả năng, không phải cấm)', 'don\'t have to'], 0, 'Mustn\'t = bị cấm.', ['Đúng — mustn\'t = bị cấm (không được hút thuốc trong bệnh viện).', 'Sai — "shouldn\'t" chỉ là lời khuyên không nên, nhẹ hơn cấm.', 'Sai — "can\'t" chỉ sự không thể/không được phép, không nhấn mạnh cấm như mustn\'t.', 'Sai — "don\'t have to" nghĩa là không cần, không phải cấm.']),
    Q('"I ___ get up early tomorrow."', ['have (thiếu \'to\' - sai cấu trúc have to)', 'musts (sai - must là modal, không thêm s)', 'have to', 'must to'], 2, 'Have to + V nguyên.', ['Sai — "have" thiếu "to", cấu trúc đúng là have to + V.', 'Sai — "musts" sai: must là modal, không thêm -s.', 'Đúng — have to + V nguyên (I have to get up early).', 'Sai — "must to" sai: must không đi với "to".']),
    Q('"You ___ study harder for the exam." (lời khuyên)', ['will (sẽ - chỉ tương lai, không phải lời khuyên)', 'must (bắt buộc - quá mạnh cho lời khuyên)', 'should', 'can (có thể - chỉ khả năng, không phải khuyên)'], 2, 'Should = nên (lời khuyên).', ['Sai — "will" chỉ tương lai, không phải lời khuyên.', 'Sai — "must" là bắt buộc, quá mạnh cho một lời khuyên.', 'Đúng — should = nên (đưa lời khuyên).', 'Sai — "can" chỉ khả năng, không phải lời khuyên.']),
    Q('"You ___ apologize to her." (nên — formal)', ['must to', 'can to', 'ought to', 'will to'], 2, 'Ought to + V nguyên = nên.', ['Sai — "must to" sai: must không đi với "to".', 'Sai — "can to" sai: can không đi với "to".', 'Đúng — ought to + V nguyên = nên (lời khuyên trang trọng).', 'Sai — "will to" sai cấu trúc, will không đi với "to".']),
  ]),

  M(13, 'Unit 7 — Viet Nam and International Organisations · Vocabulary', [
    Q('"International organisation" là?', ['Tổ chức quốc tế', 'Câu lạc bộ', 'Công ty trong nước', 'Hội từ thiện'], 0, 'Tổ chức cấp quốc tế (UN, ASEAN…).', ['Đúng — international organisation = tổ chức quốc tế (UN, ASEAN...).', 'Sai — "câu lạc bộ" là club, quy mô nhỏ, không phải tổ chức quốc tế.', 'Sai — "công ty trong nước" là domestic company, không mang tính quốc tế.', 'Sai — "hội từ thiện" là charity, không phải tổ chức cấp quốc tế.']),
    Q('"ASEAN" gồm bao nhiêu nước?', ['5', '10', '7', '15'], 1, '10 thành viên (Brunei, Cambodia, Indonesia,…).', ['Sai — 5 là số nước sáng lập ban đầu, hiện đã mở rộng.', 'Đúng — ASEAN hiện có 10 nước thành viên.', 'Sai — 7 không đúng số thành viên ASEAN.', 'Sai — 15 nhiều hơn số thành viên thực tế.']),
    Q('UN viết tắt cho?', ['United Network', 'United Nations', 'Union of Nations', 'Universal Nations'], 1, 'United Nations = Liên Hợp Quốc.', ['Sai — "United Network" không phải nghĩa của UN.', 'Đúng — UN = United Nations = Liên Hợp Quốc.', 'Sai — "Union of Nations" sai cụm từ chính thức.', 'Sai — "Universal Nations" sai cụm từ.']),
    Q('UNESCO là tổ chức về?', ['Kinh tế', 'Giáo dục, Khoa học và Văn hoá', 'Y tế thế giới (đó là WHO, không phải UNESCO)', 'Quân sự'], 1, 'UN Educational, Scientific, Cultural Organization.', ['Sai — UNESCO không phải tổ chức kinh tế.', 'Đúng — UNESCO = tổ chức về Giáo dục, Khoa học và Văn hoá.', 'Sai — y tế thế giới là WHO, không phải UNESCO.', 'Sai — UNESCO không phải tổ chức quân sự.']),
    Q('"Member state" là?', ['Tiểu bang (state - dễ nhầm do từ \'state\')', 'Vùng lãnh thổ', 'Quốc gia thành viên', 'Quan sát viên (observer - không phải thành viên chính thức)'], 2, 'Member state = thành viên chính thức.', ['Sai — "tiểu bang" là province/state nội bộ, dễ nhầm do chữ "state".', 'Sai — "vùng lãnh thổ" là territory, không phải thành viên.', 'Đúng — member state = quốc gia thành viên của tổ chức.', 'Sai — "quan sát viên" là observer, không phải thành viên chính thức.']),
    Q('"Cooperation" nghĩa là?', ['Sự độc lập', 'Sự đối đầu', 'Sự hợp tác', 'Sự cạnh tranh'], 2, 'Cooperation = hợp tác.', ['Sai — "sự độc lập" là independence, sai nghĩa.', 'Sai — "sự đối đầu" là confrontation, ngược nghĩa.', 'Đúng — cooperation = sự hợp tác.', 'Sai — "sự cạnh tranh" là competition, ngược nghĩa.']),
  ]),

  M(14, 'Unit 7 — Reported Speech (statements)', [
    Q('Đổi sang gián tiếp: "She said, ‘I am happy.’"', ['She said she be happy.', 'She said she is happy.', 'She said she will be happy.', 'She said (that) she was happy.'], 3, 'Lùi thì: am → was.', ['Sai — "She said she be happy" sai dạng động từ, thiếu was.', 'Sai — "She said she is happy" không lùi thì (is → was).', 'Sai — "She said she will be happy" sai thì, không có will trong câu gốc.', 'Đúng — lùi thì: am → was = She said (that) she was happy.']),
    Q('"He said, ‘I will come tomorrow.’" → ?', ['He said he comes tomorrow.', 'He said he will come tomorrow.', 'He said he came tomorrow.', 'He said (that) he would come the next day.'], 3, 'Will → would, tomorrow → the next day.', ['Sai — "he comes tomorrow" không lùi thì và không đổi trạng từ.', 'Sai — "he will come tomorrow" không lùi will → would.', 'Sai — "he came tomorrow" sai: came không hợp với "tomorrow".', 'Đúng — will → would, tomorrow → the next day.']),
    Q('Lùi thì present simple → ?', ['past continuous', 'future', 'past simple', 'present perfect'], 2, 'Present simple → past simple.', ['Sai — present simple không lùi thành past continuous.', 'Sai — present simple không lùi thành future.', 'Đúng — lùi thì: present simple → past simple.', 'Sai — present simple không lùi thành present perfect.']),
    Q('"now" trong gián tiếp đổi thành?', ['that day (đổi cho \'today\', không phải \'now\')', 'yesterday', 'then', 'tomorrow'], 2, 'now → then.', ['Sai — "that day" là dạng đổi của "today", không phải "now".', 'Sai — "yesterday" không phải dạng đổi của "now".', 'Đúng — trong gián tiếp: now → then.', 'Sai — "tomorrow" không phải dạng đổi của "now".']),
    Q('"this" trong gián tiếp đổi thành?', ['that', 'those (số nhiều - \'this\' số ít đổi thành \'that\')', 'those one', 'these (số nhiều, hiện tại - sai cả hai)'], 0, 'this → that.', ['Đúng — trong gián tiếp: this → that.', 'Sai — "those" là số nhiều; "this" số ít đổi thành "that".', 'Sai — "those one" sai cấu trúc.', 'Sai — "these" là số nhiều và hiện tại, sai cả hai điểm.']),
    Q('"She said, ‘I have finished.’" → ?', ['She said she finishes.', 'She said she has finished.', 'She said she finished.', 'She said she had finished.'], 3, 'Present perfect → past perfect.', ['Sai — "she finishes" không lùi thì.', 'Sai — "she has finished" không lùi present perfect → past perfect.', 'Sai — "she finished" lùi sai (chỉ thành past simple).', 'Đúng — present perfect → past perfect = she had finished.']),
  ]),

  M(15, 'Unit 8 — New Ways to Learn · Vocabulary', [
    Q('"E-learning" là?', ['Học trực tuyến', 'Học truyền thống', 'Học nhóm', 'Học tại trường'], 0, 'E-learning = học qua mạng/điện tử.', ['Đúng — e-learning = học trực tuyến/điện tử.', 'Sai — "học truyền thống" là traditional learning, ngược nghĩa.', 'Sai — "học nhóm" là group study, không phải e-learning.', 'Sai — "học tại trường" là on-campus learning, không phải online.']),
    Q('"MOOC" viết tắt cho?', ['Massive Open Online Course', 'Mobile Online Class', 'Many Open Online Class', 'Modern Online Course'], 0, 'Khoá học mở trực tuyến đại trà.', ['Đúng — MOOC = Massive Open Online Course (khoá học mở trực tuyến đại trà).', 'Sai — "Mobile Online Class" sai cụm từ.', 'Sai — "Many Open Online Class" sai cụm từ.', 'Sai — "Modern Online Course" sai cụm từ.']),
    Q('"Digital device" là?', ['Bảng đen', 'Vở ghi (notebook - dùng để học nhưng không phải digital)', 'Thiết bị kỹ thuật số', 'Thước kẻ (ruler - dụng cụ học truyền thống)'], 2, 'Smartphone, máy tính,…', ['Sai — "bảng đen" là blackboard, không phải digital.', 'Sai — "vở ghi" là notebook (giấy), không phải thiết bị số.', 'Đúng — digital device = thiết bị kỹ thuật số (điện thoại, máy tính).', 'Sai — "thước kẻ" là ruler, dụng cụ truyền thống, không phải digital.']),
    Q('"Online platform" là?', ['Nền tảng trực tuyến', 'Bệ phóng', 'Sân khấu', 'Sàn nhảy'], 0, 'Platform = nền tảng.', ['Đúng — online platform = nền tảng trực tuyến.', 'Sai — "bệ phóng" là launch pad, nghĩa đen, sai ngữ cảnh.', 'Sai — "sân khấu" là stage, sai nghĩa.', 'Sai — "sàn nhảy" là dance floor, sai nghĩa.']),
    Q('"Self-study" nghĩa là?', ['Tự học', 'Học trên lớp', 'Học nhóm', 'Học gia sư'], 0, 'Self-study = tự học.', ['Đúng — self-study = tự học.', 'Sai — "học trên lớp" là class learning, ngược nghĩa.', 'Sai — "học nhóm" là group study, không phải tự học.', 'Sai — "học gia sư" là tutoring, không phải tự học.']),
    Q('"Interactive" là?', ['Bị động', 'Im lặng', 'Cá nhân', 'Có tính tương tác'], 3, 'Interactive = tương tác.', ['Sai — "bị động" là passive, ngược nghĩa với tương tác.', 'Sai — "im lặng" là silent, sai nghĩa.', 'Sai — "cá nhân" là individual, không phải tương tác.', 'Đúng — interactive = có tính tương tác.']),
  ]),

  M(16, 'Unit 8 — Conditional Sentences Type 1 & 2', [
    Q('Type 1: "If it ___ tomorrow, we will stay home."', ['will rain', 'is raining', 'rains', 'rained'], 2, 'If + S + V_s/es, S + will + V.', ['Sai — "will rain" sai: mệnh đề if của Type 1 dùng hiện tại đơn, không will.', 'Sai — "is raining" tiếp diễn, không hợp cấu trúc Type 1.', 'Đúng — Type 1: If + S + V(s/es), S + will + V → rains.', 'Sai — "rained" là quá khứ, đó là Type 2.']),
    Q('Type 2: "If I ___ rich, I would travel the world."', ['were', 'was (đúng văn nói, nhưng Type 2 chuẩn dùng were)', 'will be', 'am (HTĐ - không phải điều kiện không có thật)'], 0, 'If + S + V_quá khứ (were với mọi ngôi), S + would + V.', ['Đúng — Type 2: If + S + were (mọi ngôi), S + would + V.', 'Sai — "was" được dùng trong văn nói nhưng chuẩn Type 2 dùng "were".', 'Sai — "will be" sai: mệnh đề if Type 2 không dùng will.', 'Sai — "am" hiện tại đơn, không phải điều kiện không có thật.']),
    Q('"If you study hard, you ___ the exam."', ['will pass', 'passed', 'would pass', 'pass (V nguyên - thiếu trợ động từ will)'], 0, 'Type 1 → will + V.', ['Đúng — Type 1: If + hiện tại đơn, S + will + V → will pass.', 'Sai — "passed" quá khứ, không hợp Type 1.', 'Sai — "would pass" là Type 2, không hợp "study" (hiện tại) trong if.', 'Sai — "pass" thiếu trợ động từ will.']),
    Q('"If I had wings, I ___ fly to you."', ['will (sẽ - dùng cho Type 1, không phải Type 2)', 'can (có thể - không phải dạng quá khứ của modal)', 'would', 'could (có thể đã - nhấn khả năng, không tự nhiên ở đây)'], 2, 'Type 2 → would + V.', ['Sai — "will" dùng cho Type 1, không hợp "had wings" (Type 2).', 'Sai — "can" sai: cần dạng quá khứ của modal trong Type 2.', 'Đúng — Type 2: If + quá khứ, S + would + V → would fly.', 'Sai — "could" nhấn khả năng, không tự nhiên bằng would ở đây.']),
    Q('Type 1 dùng cho?', ['Điều kiện không có thật ở hiện tại', 'Mệnh lệnh', 'Quá khứ', 'Điều kiện có thật ở tương lai'], 3, 'Type 1 = điều có khả năng xảy ra.', ['Sai — điều kiện không có thật ở hiện tại là Type 2, không phải Type 1.', 'Sai — Type 1 không dùng cho mệnh lệnh.', 'Sai — Type 1 không dùng cho quá khứ.', 'Đúng — Type 1 dùng cho điều kiện có thật/có khả năng ở tương lai.']),
    Q('Type 2 dùng cho?', ['Mệnh lệnh', 'Điều có thật', 'Quá khứ', 'Điều giả định trái với hiện tại'], 3, 'Type 2 = không có thật ở hiện tại.', ['Sai — Type 2 không dùng cho mệnh lệnh.', 'Sai — điều có thật là Type 1, không phải Type 2.', 'Sai — Type 2 nói về hiện tại giả định, không phải quá khứ (đó là Type 3).', 'Đúng — Type 2 dùng cho điều giả định trái với hiện tại.']),
  ]),

  M(17, 'Unit 9 — Protecting the Environment · Vocabulary', [
    Q('"Greenhouse effect" là?', ['Nhà xanh', 'Hiệu ứng nhà kính', 'Vườn hoa', 'Nhà kính trồng cây'], 1, 'Hiệu ứng nhà kính làm Trái đất nóng lên.', ['Sai — "nhà xanh" là nghĩa đen, không phải thuật ngữ.', 'Đúng — greenhouse effect = hiệu ứng nhà kính.', 'Sai — "vườn hoa" là flower garden, sai nghĩa.', 'Sai — "nhà kính trồng cây" là greenhouse (nghĩa đen), không phải hiệu ứng.']),
    Q('"Global warming" là?', ['Sự nóng lên toàn cầu', 'Mùa hè', 'Sự lạnh đi', 'Thời tiết'], 0, 'Global warming = trái đất nóng lên.', ['Đúng — global warming = sự nóng lên toàn cầu.', 'Sai — "mùa hè" là summer, sai nghĩa.', 'Sai — "sự lạnh đi" là cooling, ngược nghĩa.', 'Sai — "thời tiết" là weather, không phải global warming.']),
    Q('"Renewable energy" là?', ['Năng lượng cũ', 'Năng lượng hoá thạch', 'Năng lượng hạt nhân', 'Năng lượng tái tạo'], 3, 'Solar, wind, hydro,… là năng lượng tái tạo.', ['Sai — "năng lượng cũ" sai nghĩa, không phải renewable.', 'Sai — "năng lượng hoá thạch" là fossil energy, không tái tạo được.', 'Sai — "năng lượng hạt nhân" là nuclear, không phải renewable.', 'Đúng — renewable energy = năng lượng tái tạo (mặt trời, gió, nước).']),
    Q('"Solar power" là?', ['Thuỷ điện', 'Năng lượng mặt trời', 'Hạt nhân', 'Năng lượng gió'], 1, 'Solar = mặt trời.', ['Sai — "thuỷ điện" là hydropower, không phải solar.', 'Đúng — solar power = năng lượng mặt trời.', 'Sai — "hạt nhân" là nuclear, sai nghĩa.', 'Sai — "năng lượng gió" là wind power, không phải solar.']),
    Q('"Conservation" nghĩa là?', ['Sự ô nhiễm', 'Sự phá huỷ', 'Sự bảo tồn', 'Sự xây dựng'], 2, 'Conservation = bảo tồn (môi trường, loài,…).', ['Sai — "sự ô nhiễm" là pollution, ngược nghĩa.', 'Sai — "sự phá huỷ" là destruction, ngược nghĩa.', 'Đúng — conservation = sự bảo tồn (môi trường, loài).', 'Sai — "sự xây dựng" là construction, dễ nhầm âm nhưng khác nghĩa.']),
    Q('"Eco-friendly" là?', ['Thân thiện môi trường', 'Cao cấp', 'Đắt tiền', 'Khó dùng'], 0, 'Eco-friendly = thân thiện với môi trường.', ['Đúng — eco-friendly = thân thiện với môi trường.', 'Sai — "cao cấp" là premium, sai nghĩa.', 'Sai — "đắt tiền" là expensive, không liên quan.', 'Sai — "khó dùng" là hard to use, sai nghĩa.']),
  ]),

  M(18, 'Ôn tập học kỳ 1', [
    Q('Thì present simple chia với ngôi 3 số ít?', ['Giữ nguyên', 'Thêm -ing', 'Thêm -s/-es', 'Thêm -ed'], 2, 'He, she, it + V_s/es.', ['Sai — không giữ nguyên: ngôi 3 số ít cần thêm -s/-es.', 'Sai — thêm -ing là hiện tại tiếp diễn, không phải hiện tại đơn.', 'Đúng — ngôi 3 số ít (he/she/it) + V → thêm -s/-es.', 'Sai — thêm -ed là quá khứ đơn, không phải hiện tại đơn.']),
    Q('Câu bị động: "They built this bridge in 1990." → ?', ['This bridge was built in 1990.', 'This bridge built in 1990.', 'This bridge is built in 1990.', 'This bridge has built in 1990.'], 0, 'Quá khứ bị động: was/were + V3.', ['Đúng — quá khứ bị động: was/were + V3 = was built in 1990.', 'Sai — "This bridge built in 1990" thiếu was, sai dạng bị động.', 'Sai — "is built" là hiện tại, không hợp mốc 1990.', 'Sai — "has built" sai dạng: bị động cần was built.']),
    Q('Reported: "He said, ‘I am tired.’" → ?', ['He said he be tired.', 'He said he was tired.', 'He said he is tired.', 'He said he tired.'], 1, 'Lùi thì: am → was.', ['Sai — "he be tired" sai dạng động từ, thiếu was.', 'Đúng — lùi thì: am → was = He said he was tired.', 'Sai — "he is tired" không lùi thì.', 'Sai — "he tired" thiếu động từ to be.']),
    Q('Type 2 conditional: "If I ___ a bird…"', ['am (HTĐ - không phải điều kiện không thực)', 'was (văn nói chấp nhận, nhưng chuẩn Type 2 là were)', 'will be', 'were'], 3, 'Were dùng với mọi ngôi trong type 2.', ['Sai — "am" hiện tại đơn, không phải điều kiện không thực.', 'Sai — "was" văn nói chấp nhận nhưng chuẩn Type 2 dùng "were".', 'Sai — "will be" không dùng trong mệnh đề if Type 2.', 'Đúng — Type 2 dùng "were" với mọi ngôi (If I were a bird).']),
    Q('Must vs Should: lời khuyên dùng?', ['have to', 'must (bắt buộc - mạnh hơn lời khuyên)', 'should', 'can (có thể - chỉ khả năng, không khuyên)'], 2, 'Should = nên.', ['Sai — "have to" là bắt buộc, không phải lời khuyên nhẹ.', 'Sai — "must" là bắt buộc, quá mạnh cho lời khuyên.', 'Đúng — should = nên (đưa lời khuyên).', 'Sai — "can" chỉ khả năng, không phải lời khuyên.']),
    Q('"Renewable" energy gồm?', ['wood, biomass (gỗ - có tái tạo nhưng không phải ví dụ chuẩn)', 'coal, oil, gas', 'nuclear', 'solar, wind, hydro'], 3, 'Năng lượng tái tạo từ thiên nhiên.', ['Sai — "wood, biomass" có tái tạo nhưng không phải ví dụ điển hình nhất.', 'Sai — "coal, oil, gas" là nhiên liệu hoá thạch, không tái tạo.', 'Sai — "nuclear" là năng lượng hạt nhân, không phải tái tạo.', 'Đúng — solar, wind, hydro là năng lượng tái tạo điển hình.']),
  ]),

  // ──────────────── HK2 ────────────────
  M(19, 'Unit 9 — Conditional Type 3 & Mixed Conditional', [
    Q('Type 3: "If I ___ harder, I would have passed."', ['studied', 'will study', 'had studied', 'study (V nguyên - không phải Type 3)'], 2, 'If + S + had + V3, S + would have + V3.', ['Sai — "studied" quá khứ đơn, mệnh đề if Type 3 cần past perfect.', 'Sai — "will study" không dùng trong if Type 3.', 'Đúng — Type 3: If + had + V3 = had studied.', 'Sai — "study" V nguyên, sai cấu trúc Type 3.']),
    Q('"If she had told me, I ___ helped her."', ['will have', 'would have', 'would (Type 2 - không hợp với \'had told\')', 'had (đã - thiếu \'have\' phía sau)'], 1, 'Type 3: would have + V3.', ['Sai — "will have" không dùng cho điều kiện không thực quá khứ.', 'Đúng — Type 3: would have + V3 = would have helped.', 'Sai — "would" là Type 2, không hợp "had told" (Type 3).', 'Sai — "had" thiếu "have" phía sau, sai dạng.']),
    Q('Type 3 nói về?', ['Điều giả định trái với quá khứ', 'Hiện tại có thật', 'Tương lai có thật', 'Hiện tại không có thật'], 0, 'Sự việc đã qua không thể thay đổi.', ['Đúng — Type 3 nói về điều giả định trái với quá khứ (đã không xảy ra).', 'Sai — hiện tại có thật là Type 0/1, không phải Type 3.', 'Sai — tương lai có thật là Type 1, không phải Type 3.', 'Sai — hiện tại không có thật là Type 2, không phải Type 3.']),
    Q('Mixed: "If I had studied medicine, I ___ a doctor now."', ['would be', 'will be', 'am (HTĐ - không phải dạng điều kiện)', 'would have been'], 0, 'Điều kiện quá khứ + kết quả hiện tại: had + V3 / would + V.', ['Đúng — Mixed: If + had + V3 (quá khứ) → would + V (kết quả hiện tại) = would be.', 'Sai — "will be" không dùng cho điều kiện không thực.', 'Sai — "am" hiện tại đơn, không phải dạng điều kiện.', 'Sai — "would have been" là kết quả quá khứ, ở đây là kết quả hiện tại (now).']),
    Q('"If you hadn\'t helped me, I ___ failed."', ['had (đã - thiếu \'have\' và sai dạng)', 'will have', 'would (Type 2 - không hợp với \'hadn\'t helped\')', 'would have'], 3, 'Type 3 phủ định trong if.', ['Sai — "had" thiếu "have" và sai dạng kết quả.', 'Sai — "will have" không dùng cho điều kiện không thực quá khứ.', 'Sai — "would" là Type 2, không hợp "hadn\'t helped" (Type 3).', 'Đúng — Type 3: would have + V3 = would have failed.']),
    Q('Dấu hiệu type 3 là?', ['had + V3 trong mệnh đề if', 'Will trong mệnh đề if', 'V_ing trong if', 'V_s trong mệnh đề if'], 0, 'Past perfect trong if.', ['Đúng — dấu hiệu Type 3 là "had + V3" trong mệnh đề if.', 'Sai — "will" không xuất hiện trong mệnh đề if.', 'Sai — "V-ing" không phải dấu hiệu Type 3.', 'Sai — "V-s" trong if là dấu hiệu Type 1, không phải Type 3.']),
  ]),

  M(20, 'Unit 10 — Ecotourism · Vocabulary', [
    Q('"Ecotourism" là?', ['Du lịch sang trọng', 'Du lịch sinh thái', 'Du lịch giá rẻ', 'Du lịch quân sự'], 1, 'Eco + tourism = du lịch sinh thái.', ['Sai — "du lịch sang trọng" là luxury tourism, sai nghĩa.', 'Đúng — ecotourism = du lịch sinh thái (eco + tourism).', 'Sai — "du lịch giá rẻ" là budget tourism, không phải eco.', 'Sai — "du lịch quân sự" sai hoàn toàn nghĩa.']),
    Q('"Sustainable" nghĩa là?', ['Nhanh chóng', 'Bền vững', 'Tạm thời', 'Đắt đỏ'], 1, 'Sustainable = bền vững.', ['Sai — "nhanh chóng" là quick, sai nghĩa.', 'Đúng — sustainable = bền vững.', 'Sai — "tạm thời" là temporary, ngược nghĩa.', 'Sai — "đắt đỏ" là expensive, không liên quan.']),
    Q('"Biodiversity" là?', ['Toán học', 'Hoá học', 'Vật lý', 'Đa dạng sinh học'], 3, 'Bio + diversity = đa dạng các loài sống.', ['Sai — "toán học" là mathematics, sai nghĩa.', 'Sai — "hoá học" là chemistry, sai nghĩa.', 'Sai — "vật lý" là physics, sai nghĩa.', 'Đúng — biodiversity = đa dạng sinh học (bio + diversity).']),
    Q('"Wildlife" là?', ['Vườn cây', 'Nông sản', 'Thú nuôi', 'Động thực vật hoang dã'], 3, 'Wildlife = sinh vật hoang dã.', ['Sai — "vườn cây" là garden, sai nghĩa.', 'Sai — "nông sản" là farm produce, sai nghĩa.', 'Sai — "thú nuôi" là pets, ngược với hoang dã.', 'Đúng — wildlife = động thực vật hoang dã.']),
    Q('"Habitat" nghĩa là?', ['Môi trường sống', 'Người dân', 'Đường phố', 'Nhà ở người'], 0, 'Habitat = nơi cư trú của loài.', ['Đúng — habitat = môi trường sống/nơi cư trú của loài.', 'Sai — "người dân" là residents, sai nghĩa.', 'Sai — "đường phố" là street, sai nghĩa.', 'Sai — "nhà ở người" là human housing, không phải habitat tự nhiên.']),
    Q('"To preserve" là?', ['Phá hủy', 'Khai thác (exploit - ngược nghĩa với bảo tồn)', 'Bảo tồn, giữ gìn', 'Ô nhiễm'], 2, 'Preserve = giữ gìn nguyên trạng.', ['Sai — "phá huỷ" là destroy, ngược nghĩa.', 'Sai — "khai thác" là exploit, ngược với bảo tồn.', 'Đúng — preserve = bảo tồn, giữ gìn nguyên trạng.', 'Sai — "ô nhiễm" là pollute, ngược nghĩa.']),
  ]),

  M(21, 'Unit 10 — Gerunds and Infinitives', [
    Q('"I enjoy ___ books."', ['read (V nguyên - enjoy luôn theo V-ing)', 'reads (HTĐ ngôi 3 - sai cấu trúc)', 'to read', 'reading'], 3, 'Enjoy + V-ing.', ['Sai — "read" V nguyên: enjoy luôn theo sau bởi V-ing.', 'Sai — "reads" ngôi 3, sai cấu trúc sau enjoy.', 'Sai — "to read" sai: enjoy + V-ing chứ không + to V.', 'Đúng — enjoy + V-ing = enjoy reading.']),
    Q('"She wants ___ a doctor."', ['be (V nguyên - thiếu \'to\' sau want)', 'being (V-ing - want không theo V-ing)', 'to being', 'to be'], 3, 'Want + to V.', ['Sai — "be" V nguyên thiếu "to" sau want.', 'Sai — "being" V-ing: want không đi với V-ing.', 'Sai — "to being" sai cấu trúc.', 'Đúng — want + to V = want to be.']),
    Q('"He suggested ___ a movie."', ['watched', 'watching', 'watch (V nguyên - suggest không theo V nguyên)', 'to watch'], 1, 'Suggest + V-ing.', ['Sai — "watched" quá khứ, sai cấu trúc sau suggest.', 'Đúng — suggest + V-ing = suggested watching.', 'Sai — "watch" V nguyên: suggest không đi với V nguyên.', 'Sai — "to watch" sai: suggest + V-ing chứ không + to V.']),
    Q('"I hope ___ you soon."', ['sees (HTĐ ngôi 3 - không hợp sau hope)', 'to see', 'see (V nguyên - thiếu \'to\')', 'seeing'], 1, 'Hope + to V.', ['Sai — "sees" ngôi 3, sai sau hope.', 'Đúng — hope + to V = hope to see.', 'Sai — "see" V nguyên thiếu "to".', 'Sai — "seeing" V-ing: hope đi với to V, không V-ing.']),
    Q('"Stop ___!" (đừng nói chuyện nữa)', ['talking', 'talk (V nguyên - Stop theo V-ing để dừng)', 'to talk', 'talks (HTĐ ngôi 3 - sai cấu trúc)'], 0, 'Stop V-ing = dừng việc đang làm.', ['Đúng — stop + V-ing = dừng việc đang làm (stop talking = ngừng nói).', 'Sai — "talk" V nguyên, sai cấu trúc.', 'Sai — "to talk" nghĩa khác: stop to talk = dừng lại để nói (mục đích).', 'Sai — "talks" ngôi 3, sai cấu trúc.']),
    Q('"He decided ___ abroad."', ['to study', 'studying', 'studied', 'study (V nguyên - decide cần \'to\')'], 0, 'Decide + to V.', ['Đúng — decide + to V = decided to study.', 'Sai — "studying" V-ing: decide đi với to V.', 'Sai — "studied" quá khứ, sai cấu trúc sau decide.', 'Sai — "study" V nguyên thiếu "to".']),
  ]),

  M(22, 'Reported Speech — Questions & Commands', [
    Q('Yes/No question: "She asked, ‘Do you like coffee?’" → ?', ['She asked I like coffee.', 'She asked if I liked coffee.', 'She asked do I like coffee.', 'She asked if did I like coffee.'], 1, 'Dùng if/whether + S + V (lùi thì).', ['Sai — "She asked I like coffee" thiếu if/whether và không lùi thì.', 'Đúng — câu hỏi Yes/No → if/whether + S + V (lùi thì) = if I liked coffee.', 'Sai — "She asked do I like coffee" giữ trợ động từ do, sai.', 'Sai — "if did I like coffee" đảo ngữ + lùi thì, sai cấu trúc.']),
    Q('WH-question: "He asked, ‘Where do you live?’" → ?', ['He asked where do I live.', 'He asked where I live.', 'He asked where I lived.', 'He asked where did I live.'], 2, 'Giữ từ để hỏi + S + V (không có trợ động từ).', ['Sai — "where do I live" giữ trợ động từ do, sai.', 'Sai — "where I live" không lùi thì (live → lived).', 'Đúng — giữ từ hỏi + S + V (lùi thì, bỏ trợ động từ) = where I lived.', 'Sai — "where did I live" đảo ngữ với did, sai cấu trúc gián tiếp.']),
    Q('Command: "He said, ‘Open the door!’" → ?', ['He told me open the door.', 'He said me to open.', 'He said open the door.', 'He told me to open the door.'], 3, 'Told + O + to V.', ['Sai — "He told me open" thiếu "to" trước open.', 'Sai — "He said me to open" sai: said không đi với tân ngữ kiểu này.', 'Sai — "He said open the door" giữ nguyên mệnh lệnh, không chuyển gián tiếp.', 'Đúng — câu mệnh lệnh: told + O + to V = told me to open the door.']),
    Q('Negative command: "She said, ‘Don\'t shout!’" → ?', ['She told me don\'t shout.', 'She told to not shout.', 'She told me not to shout.', 'She said not shout.'], 2, 'Not + to V.', ['Sai — "told me don\'t shout" giữ don\'t, sai cấu trúc gián tiếp.', 'Sai — "told to not shout" thiếu tân ngữ me, sai vị trí not.', 'Đúng — mệnh lệnh phủ định: told + O + not to V = told me not to shout.', 'Sai — "said not shout" thiếu "to", sai cấu trúc.']),
    Q('"asked" thường dùng cho?', ['Câu cảm thán', 'Câu hỏi', 'Câu mệnh lệnh', 'Câu khẳng định'], 1, 'Ask dùng cho câu hỏi trong gián tiếp.', ['Sai — câu cảm thán không dùng "asked".', 'Đúng — "asked" dùng để tường thuật câu hỏi.', 'Sai — câu mệnh lệnh thường dùng "told"/"asked sb to", không nhấn câu hỏi.', 'Sai — câu khẳng định dùng "said", không phải "asked".']),
    Q('Lùi thì past simple → ?', ['past continuous', 'present perfect', 'past simple', 'past perfect'], 3, 'Past simple → past perfect.', ['Sai — past simple không lùi thành past continuous.', 'Sai — past simple không lùi thành present perfect.', 'Sai — past simple lùi thì phải đổi, không giữ nguyên past simple.', 'Đúng — lùi thì: past simple → past perfect.']),
  ]),

  M(23, 'Relative Clauses — Defining vs Non-defining', [
    Q('"The man ___ is wearing glasses is my uncle."', ['which (dùng cho vật, không cho người)', 'whose (sở hữu - không phải chủ ngữ)', 'where (nơi chốn - không phải người)', 'who'], 3, 'Who: chỉ người (chủ ngữ).', ['Sai — "which" dùng cho vật, không cho người.', 'Sai — "whose" chỉ sở hữu, không phải chủ ngữ chỉ người.', 'Sai — "where" chỉ nơi chốn, không phải người.', 'Đúng — who: đại từ quan hệ chỉ người làm chủ ngữ.']),
    Q('"The book ___ I bought is interesting."', ['which/that', 'whose (sở hữu - không phải tân ngữ vật)', 'who (chỉ người - sách là vật)', 'where (nơi chốn - sách không phải nơi)'], 0, 'Which/that: chỉ vật.', ['Đúng — which/that: chỉ vật (the book) làm tân ngữ.', 'Sai — "whose" chỉ sở hữu, không phải tân ngữ chỉ vật.', 'Sai — "who" chỉ người; sách là vật.', 'Sai — "where" chỉ nơi chốn; sách không phải nơi.']),
    Q('"The girl ___ mother is a doctor is my friend."', ['whose', 'who (chủ ngữ người - không thể hiện sở hữu)', 'which (vật - không phải sở hữu)', 'where (nơi chốn - không chỉ sở hữu)'], 0, 'Whose: chỉ sở hữu.', ['Đúng — whose: chỉ sở hữu (the girl whose mother...).', 'Sai — "who" làm chủ ngữ chỉ người, không thể hiện sở hữu.', 'Sai — "which" chỉ vật, không phải sở hữu.', 'Sai — "where" chỉ nơi chốn, không chỉ sở hữu.']),
    Q('Mệnh đề quan hệ không xác định cần?', ['Không dấu', 'Dấu phẩy', 'Dấu chấm', 'Dấu ngoặc'], 1, 'Non-defining clause có dấu phẩy bao quanh.', ['Sai — "không dấu" sai: mệnh đề không xác định cần dấu phẩy.', 'Đúng — mệnh đề quan hệ không xác định (non-defining) cần dấu phẩy bao quanh.', 'Sai — "dấu chấm" không bao mệnh đề quan hệ.', 'Sai — "dấu ngoặc" không phải dấu của non-defining clause.']),
    Q('"My father, ___ is 50, works in a bank." Chọn?', ['which (vật - cha không phải vật)', 'that (không dùng trong non-defining)', 'who', 'whose (sở hữu - không hợp ngữ cảnh)'], 2, 'Non-defining + người → who (không dùng that).', ['Sai — "which" chỉ vật; cha (My father) là người.', 'Sai — "that" không dùng trong mệnh đề không xác định (non-defining).', 'Đúng — non-defining + người → who (không dùng that).', 'Sai — "whose" chỉ sở hữu, không hợp ngữ cảnh.']),
    Q('"The school ___ I studied is in Hanoi."', ['where', 'whose (sở hữu - không phải nơi chốn)', 'which (vật - cần giới từ in phía sau)', 'who (người - không phải nơi)'], 0, 'Where: chỉ nơi chốn.', ['Đúng — where: chỉ nơi chốn (the school where I studied).', 'Sai — "whose" chỉ sở hữu, không phải nơi chốn.', 'Sai — "which" chỉ vật, cần thêm giới từ "in" nếu dùng.', 'Sai — "who" chỉ người, không phải nơi chốn.']),
  ]),

  M(24, 'Articles — A, An, The', [
    Q('"I have ___ apple."', ['the (xác định - apple ở đây không xác định)', 'no article', 'a (đứng trước phụ âm - apple bắt đầu nguyên âm)', 'an'], 3, 'Apple bắt đầu bằng nguyên âm → an.', ['Sai — "the" chỉ vật xác định; ở đây apple chưa xác định.', 'Sai — "no article" sai: danh từ đếm được số ít cần mạo từ.', 'Sai — "a" đứng trước phụ âm; apple bắt đầu bằng nguyên âm.', 'Đúng — apple bắt đầu bằng nguyên âm → an apple.']),
    Q('"___ sun rises in the east."', ['An (đứng trước nguyên âm - sun bắt đầu phụ âm)', 'The', 'A (không xác định - sun là duy nhất)', '— (cần mạo từ vì sun là vật duy nhất)'], 1, 'Sun là duy nhất → the.', ['Sai — "An" đứng trước nguyên âm; sun bắt đầu bằng phụ âm.', 'Đúng — sun là vật duy nhất → the sun.', 'Sai — "A" chỉ vật không xác định; sun là duy nhất nên dùng the.', 'Sai — bỏ mạo từ sai: sun là vật duy nhất, cần "the".']),
    Q('"She is ___ honest person."', ['— (thiếu mạo từ - cần \'an\' trước honest)', 'an', 'the (xác định - đây là giới thiệu chung)', 'a (đứng trước phụ âm - honest có h câm)'], 1, '"H" câm, đọc /ɒnɪst/ → an.', ['Sai — bỏ mạo từ sai: cần "an" trước honest.', 'Đúng — "h" trong honest là âm câm, đọc /ɒnɪst/ → an honest.', 'Sai — "the" chỉ xác định; ở đây là giới thiệu chung.', 'Sai — "a" đứng trước âm phụ âm; honest có "h" câm nên dùng an.']),
    Q('"I like ___ music."', ['the (xác định - music ở đây nói chung)', 'an (đếm được - music là danh từ không đếm được)', '—', 'a (đếm được - music không đếm được)'], 2, 'Music chung chung → không article.', ['Sai — "the" chỉ xác định; music ở đây nói chung.', 'Sai — "an" cho danh từ đếm được; music là không đếm được.', 'Đúng — music mang nghĩa chung chung → không dùng mạo từ.', 'Sai — "a" cho danh từ đếm được; music không đếm được.']),
    Q('"___ Eiffel Tower is in Paris."', ['— (không mạo từ - công trình nổi tiếng cần \'the\')', 'An (không xác định - tên riêng cần \'the\')', 'A (không xác định - tên riêng cần \'the\')', 'The'], 3, 'Tên công trình nổi tiếng → the.', ['Sai — bỏ mạo từ sai: tên công trình nổi tiếng cần "the".', 'Sai — "An" cho danh từ không xác định; tên riêng dùng the.', 'Sai — "A" cho danh từ không xác định; tên riêng dùng the.', 'Đúng — tên công trình nổi tiếng → the Eiffel Tower.']),
    Q('"He plays ___ guitar."', ['a (không xác định - nhạc cụ chuẩn dùng \'the\')', 'an (đứng trước nguyên âm - guitar bắt đầu phụ âm)', 'the', '— (cần \'the\' khi chơi nhạc cụ)'], 2, 'Chơi nhạc cụ → the.', ['Sai — "a" không xác định; chơi nhạc cụ chuẩn dùng "the".', 'Sai — "an" đứng trước nguyên âm; guitar bắt đầu phụ âm.', 'Đúng — chơi nhạc cụ → the + instrument = play the guitar.', 'Sai — bỏ mạo từ sai: chơi nhạc cụ cần "the".']),
  ]),

  M(25, 'Tenses Review — All Major Tenses', [
    Q('"I ___ to school every day."', ['am going', 'go', 'went (QKĐ - không hợp \'every day\')', 'have gone'], 1, '"Every day" → present simple.', ['Sai — "am going" tiếp diễn, không hợp thói quen "every day".', 'Đúng — "every day" → hiện tại đơn go.', 'Sai — "went" quá khứ, không hợp "every day".', 'Sai — "have gone" hiện tại hoàn thành, không hợp thói quen.']),
    Q('"He ___ TV when I called."', ['watched', 'watches', 'was watching', 'is watching'], 2, 'Hành động đang diễn ra trong quá khứ.', ['Sai — "watched" quá khứ đơn, không nhấn đang diễn ra.', 'Sai — "watches" hiện tại đơn, mâu thuẫn "called" (quá khứ).', 'Đúng — hành động đang diễn ra trong quá khứ (was watching) bị called cắt ngang.', 'Sai — "is watching" hiện tại, mâu thuẫn "called".']),
    Q('"By next year, she ___ here for 10 years."', ['lived (QKĐ - không hợp \'by next year\')', 'will live', 'will have lived', 'has lived'], 2, 'Future perfect: by + thời gian tương lai.', ['Sai — "lived" quá khứ, không hợp "by next year" (tương lai).', 'Sai — "will live" tương lai đơn, không diễn tả hoàn tất tới mốc tương lai.', 'Đúng — "by + thời gian tương lai" → tương lai hoàn thành will have lived.', 'Sai — "has lived" hiện tại hoàn thành, không hợp "by next year".']),
    Q('"I ___ this book before."', ['am reading', 'have read', 'was reading', 'read (QKĐ - không hợp \'before\' chỉ kinh nghiệm)'], 1, '"Before" + kinh nghiệm → present perfect.', ['Sai — "am reading" tiếp diễn, không hợp "before" (kinh nghiệm).', 'Đúng — "before" chỉ kinh nghiệm → hiện tại hoàn thành have read.', 'Sai — "was reading" quá khứ tiếp diễn, không nhấn kinh nghiệm tới giờ.', 'Sai — "read" quá khứ đơn, không hợp "before" chỉ kinh nghiệm tích luỹ.']),
    Q('"They ___ for 2 hours when I arrived."', ['wait (V nguyên - không hợp \'2 hours when I arrived\')', 'had been waiting', 'have waited', 'waited'], 1, 'Past perfect continuous: hành động kéo dài đến mốc quá khứ.', ['Sai — "wait" thiếu trợ động từ, sai cấu trúc.', 'Đúng — hành động kéo dài đến mốc quá khứ → quá khứ hoàn thành tiếp diễn had been waiting.', 'Sai — "have waited" hiện tại hoàn thành, không hợp "when I arrived" (quá khứ).', 'Sai — "waited" quá khứ đơn, không nhấn tính kéo dài tới mốc.']),
    Q('"Tomorrow at this time, I ___ a test."', ['am taking', 'take (V nguyên - thiếu trợ động từ tương lai)', 'will take', 'will be taking'], 3, 'Future continuous: hành động đang xảy ra tại thời điểm tương lai cụ thể.', ['Sai — "am taking" hiện tại tiếp diễn, không hợp "tomorrow at this time".', 'Sai — "take" thiếu trợ động từ tương lai.', 'Sai — "will take" tương lai đơn, không nhấn đang diễn ra tại thời điểm cụ thể.', 'Đúng — "tomorrow at this time" → tương lai tiếp diễn will be taking.']),
  ]),

  M(26, 'Comparison Structures', [
    Q('"She is ___ as her sister."', ['taller', 'as tall', 'tallest', 'more tall'], 1, 'As + adj + as = bằng.', ['Sai — "taller" là so sánh hơn, không hợp cấu trúc as...as.', 'Đúng — as + adj + as = bằng (as tall as her sister).', 'Sai — "tallest" so sánh nhất, không hợp cấu trúc bằng.', 'Sai — "more tall" sai dạng: tall dùng taller, không more tall.']),
    Q('"This is ___ book I\'ve ever read."', ['best (thiếu \'the\' trước so sánh nhất)', 'better', 'well (trạng từ - không phải so sánh nhất)', 'the best'], 3, 'So sánh nhất + ever V3.', ['Sai — "best" thiếu mạo từ "the" trước so sánh nhất.', 'Sai — "better" là so sánh hơn, không hợp "ever read".', 'Sai — "well" là trạng từ, không phải so sánh nhất.', 'Đúng — so sánh nhất + ever V3: the best book I\'ve ever read.']),
    Q('"The more you practise, ___ you become."', ['the better', 'better', 'best (so sánh nhất - không hợp cấu trúc đôi)', 'more better'], 0, 'Cấu trúc "the + comparative, the + comparative".', ['Đúng — cấu trúc "the + comparative, the + comparative" → the better.', 'Sai — "better" thiếu "the" trong vế hai.', 'Sai — "best" so sánh nhất, không hợp cấu trúc đôi.', 'Sai — "more better" lỗi kép, không gộp more với -er.']),
    Q('"He runs ___ than I do."', ['more fast', 'fast (nguyên cấp - thiếu hậu tố er)', 'fastest', 'faster'], 3, 'Adj 1 âm + er = faster.', ['Sai — "more fast" sai: fast dùng faster, không more fast.', 'Sai — "fast" thiếu hậu tố -er trong so sánh hơn.', 'Sai — "fastest" so sánh nhất, không đi với "than".', 'Đúng — adj 1 âm tiết + er = faster than.']),
    Q('"This problem is ___ that one."', ['less difficult as', 'less difficult than', 'little', 'lesser'], 1, 'Less + adj + than.', ['Sai — "less difficult as" sai: less đi với than, không as.', 'Đúng — less + adj + than = ít hơn (less difficult than).', 'Sai — "little" sai dạng so sánh.', 'Sai — "lesser" hiếm dùng và sai cấu trúc với than ở đây.']),
    Q('"Of the three boys, Tom is ___."', ['the youngest', 'young (nguyên cấp - cần so sánh nhất với \'of the three\')', 'more young', 'younger'], 0, 'So sánh nhất với "of the three".', ['Đúng — so sánh nhất với "of the three": the youngest.', 'Sai — "young" nguyên cấp, cần so sánh nhất với "of the three".', 'Sai — "more young" sai dạng: young dùng younger/youngest.', 'Sai — "younger" so sánh hơn, "of the three" cần so sánh nhất.']),
  ]),

  M(27, 'Passive Voice — All Tenses', [
    Q('Hiện tại đơn bị động: is/am/are + ?', ['V_s (ngôi 3 số ít - bị động cần V3)', 'V-ing (dạng hiện tại tiếp diễn chủ động)', 'V3/Ved (past participle)', 'V nguyên'], 2, 'Be + past participle.', ['Sai — "V_s" ngôi 3, bị động cần V3 (past participle).', 'Sai — "V-ing" là hiện tại tiếp diễn chủ động, không phải bị động.', 'Đúng — bị động: be + V3/Ved (past participle).', 'Sai — "V nguyên" sai: bị động cần past participle.']),
    Q('"This house ___ in 2010." (was built / built)', ['has built', 'built (V3 không có \'was\' - thiếu trợ động từ)', 'was built', 'is built'], 2, 'Quá khứ bị động: was + V3.', ['Sai — "has built" sai dạng: bị động cần was built.', 'Sai — "built" thiếu trợ động từ was, sai dạng bị động.', 'Đúng — quá khứ bị động: was + V3 = was built.', 'Sai — "is built" hiện tại, không hợp mốc 2010.']),
    Q('Present perfect passive: has/have been + ?', ['V3', 'V nguyên', 'V-ing (dạng tiếp diễn - không phải bị động hoàn thành)', 'V_s (ngôi 3 số ít - bị động cần V3)'], 0, 'Have/has been + past participle.', ['Đúng — hiện tại hoàn thành bị động: has/have been + V3.', 'Sai — "V nguyên" sai: cần past participle.', 'Sai — "V-ing" là dạng tiếp diễn, không phải bị động hoàn thành.', 'Sai — "V_s" ngôi 3, bị động cần V3.']),
    Q('"The book ___ by him." (đã được viết)', ['is writing', 'writes', 'has been written', 'wrote (QKĐ chủ động - không phải hiện tại hoàn thành bị động)'], 2, 'Present perfect bị động.', ['Sai — "is writing" tiếp diễn chủ động, không phải bị động.', 'Sai — "writes" hiện tại đơn chủ động, sai dạng.', 'Đúng — hiện tại hoàn thành bị động: has been + V3 = has been written.', 'Sai — "wrote" quá khứ chủ động, không phải hiện tại hoàn thành bị động.']),
    Q('Future bị động: will be + ?', ['V-ing (tiếp diễn chủ động - không phải bị động)', 'V3', 'V_s (ngôi 3 số ít - bị động cần V3)', 'V nguyên (chủ động - không phải bị động)'], 1, 'Will be + past participle.', ['Sai — "V-ing" tiếp diễn chủ động, không phải bị động.', 'Đúng — tương lai bị động: will be + V3.', 'Sai — "V_s" ngôi 3, bị động cần V3.', 'Sai — "V nguyên" chủ động, không phải bị động.']),
    Q('Modal bị động: must/can/should + ?', ['V-ing (tiếp diễn chủ động - không phải bị động)', 'be + V3', 'being + V3 (sai - đây là dạng tiếp diễn bị động)', 'V nguyên'], 1, 'Modal + be + V3.', ['Sai — "V-ing" tiếp diễn chủ động, không phải bị động.', 'Đúng — bị động với modal: modal + be + V3.', 'Sai — "being + V3" là dạng tiếp diễn bị động, không hợp sau modal.', 'Sai — "V nguyên" sai: cần "be + V3" sau modal.']),
  ]),

  M(28, 'Modal Verbs — All Types (can, could, may, might)', [
    Q('"___ I borrow your pen?" (lịch sự)', ['May', 'Will (sẽ - chỉ tương lai, không lịch sự bằng May)', 'Must (bắt buộc - không lịch sự khi xin phép)', 'Can (có thể - lịch sự nhưng May trang trọng hơn)'], 0, 'May lịch sự nhất.', ['Đúng — May lịch sự/trang trọng nhất khi xin phép.', 'Sai — "Will" chỉ tương lai, không lịch sự bằng May khi xin phép.', 'Sai — "Must" là bắt buộc, không phù hợp khi xin phép.', 'Sai — "Can" lịch sự nhưng May trang trọng hơn trong ngữ cảnh này.']),
    Q('"She ___ swim very well." (khả năng)', ['can', 'must (bắt buộc - không phải khả năng)', 'should', 'will (sẽ - chỉ tương lai, không phải khả năng)'], 0, 'Can = có thể.', ['Đúng — can = có thể (diễn tả khả năng).', 'Sai — "must" là bắt buộc, không phải khả năng.', 'Sai — "should" là lời khuyên, không phải khả năng.', 'Sai — "will" chỉ tương lai, không phải khả năng.']),
    Q('"It ___ rain tomorrow." (có thể)', ['will (chắc chắn sẽ - mạnh hơn \'có thể\')', 'might', 'should', 'must (chắc hẳn - quá chắc chắn cho dự báo)'], 1, 'Might = có thể/có khả năng.', ['Sai — "will" chắc chắn sẽ, mạnh hơn nghĩa "có thể".', 'Đúng — might = có thể/có khả năng (suy đoán không chắc).', 'Sai — "should" là lời khuyên/dự kiến, không hợp "có thể".', 'Sai — "must" chắc hẳn, quá chắc chắn cho một dự báo.']),
    Q('"You ___ have told me!" (trách)', ['should', 'could', 'can (hiện tại - không nói được việc đã qua)', 'must (bắt buộc - không hợp ngữ cảnh trách)'], 1, 'Could have + V3 = đáng lẽ đã có thể.', ['Sai — "should" có thể dùng nhưng câu nhấn khả năng đã có → could have.', 'Đúng — could have + V3 = đáng lẽ đã có thể (trách nhẹ).', 'Sai — "can" là hiện tại, không nói được việc đã qua.', 'Sai — "must" là bắt buộc, không hợp ngữ cảnh trách.']),
    Q('"He ___ be home now." (có thể đang)', ['will (chắc chắn - quá mạnh cho suy đoán)', 'can (khả năng - không dùng cho suy đoán hiện tại)', 'may', 'must (chắc hẳn - quá chắc cho \'có thể đang\')'], 2, 'May/might = có thể.', ['Sai — "will" chắc chắn, quá mạnh cho suy đoán.', 'Sai — "can" chỉ khả năng, không dùng cho suy đoán hiện tại.', 'Đúng — may/might = có thể (suy đoán) → may be home now.', 'Sai — "must" chắc hẳn, quá chắc cho nghĩa "có thể đang".']),
    Q('"You ___ be tired after a long trip." (chắc hẳn)', ['must', 'can (có thể - chỉ khả năng, không phải suy đoán chắc)', 'should', 'may (có lẽ - suy đoán nhẹ, không chắc chắn)'], 0, 'Must = chắc hẳn (suy đoán chắc chắn).', ['Đúng — must = chắc hẳn (suy đoán chắc chắn về hiện tại).', 'Sai — "can" chỉ khả năng, không phải suy đoán chắc chắn.', 'Sai — "should" là dự kiến/lời khuyên, không phải suy đoán chắc.', 'Sai — "may" là suy đoán nhẹ, không chắc bằng must.']),
  ]),

  M(29, 'Vocabulary Review — All Units', [
    Q('"Recycle" = ?', ['Sản xuất (produce - ngược nghĩa tái chế)', 'Tái chế', 'Sử dụng lại (reuse - khái niệm gần nhưng khác)', 'Vứt bỏ'], 1, 'Re-cycle = tái chế.', ['Sai — "sản xuất" là produce, ngược nghĩa tái chế.', 'Đúng — recycle = tái chế.', 'Sai — "sử dụng lại" là reuse, khái niệm gần nhưng khác.', 'Sai — "vứt bỏ" là throw away, ngược nghĩa.']),
    Q('"Volunteer" = ?', ['Khách mời (guest - dễ nhầm vì v gần âm)', 'Tình nguyện viên', 'Học sinh', 'Bác sĩ'], 1, 'Volunteer = TNV.', ['Sai — "khách mời" là guest, dễ nhầm âm nhưng khác nghĩa.', 'Đúng — volunteer = tình nguyện viên.', 'Sai — "học sinh" là student, sai nghĩa.', 'Sai — "bác sĩ" là doctor, sai nghĩa.']),
    Q('"Composer" = ?', ['Ca sĩ (singer - dễ nhầm vì cùng lĩnh vực)', 'Đạo diễn', 'Nhà soạn nhạc', 'Nhạc công'], 2, 'Composer = nhà soạn nhạc.', ['Sai — "ca sĩ" là singer, dễ nhầm cùng lĩnh vực nhưng khác.', 'Sai — "đạo diễn" là director, sai nghĩa.', 'Đúng — composer = nhà soạn nhạc.', 'Sai — "nhạc công" là musician/player, không phải người sáng tác.']),
    Q('"Invention" = ?', ['Phát minh', 'Quyền sáng chế (patent - kết quả của phát minh)', 'Khám phá', 'Sản phẩm'], 0, 'Invent = sáng chế.', ['Đúng — invention = phát minh.', 'Sai — "quyền sáng chế" là patent, kết quả pháp lý của phát minh.', 'Sai — "khám phá" là discovery, khác bản chất.', 'Sai — "sản phẩm" là product, không phải invention.']),
    Q('"Equality" = ?', ['Sự đối lập', 'Sự bình đẳng', 'Sự khác biệt', 'Sự giống nhau'], 1, 'Equality = bình đẳng.', ['Sai — "sự đối lập" là opposition, sai nghĩa.', 'Đúng — equality = sự bình đẳng.', 'Sai — "sự khác biệt" là difference, ngược nghĩa.', 'Sai — "sự giống nhau" là similarity, không phải equality.']),
    Q('"Renewable" = ?', ['Một lần', 'Hết hạn', 'Không tái sử dụng (non-reusable - khái niệm ngược)', 'Tái tạo'], 3, 'Renewable = có thể tái tạo.', ['Sai — "một lần" là single-use, không phải renewable.', 'Sai — "hết hạn" là expired, sai nghĩa.', 'Sai — "không tái sử dụng" là non-reusable, ngược nghĩa.', 'Đúng — renewable = có thể tái tạo.']),
  ]),

  M(30, 'Reading Skills — Practice', [
    Q('Để tìm ý chính của đoạn văn, đọc?', ['Đọc câu cuối', 'Câu chủ đề (thường đầu/cuối đoạn)', 'Bỏ qua', 'Toàn bộ chậm'], 1, 'Câu chủ đề (topic sentence) chứa ý chính.', ['Sai — đọc riêng câu cuối chưa đủ để nắm ý chính toàn đoạn.', 'Đúng — câu chủ đề (topic sentence, thường đầu/cuối đoạn) chứa ý chính.', 'Sai — "bỏ qua" không giúp tìm ý chính.', 'Sai — đọc toàn bộ thật chậm tốn thời gian, không hiệu quả để nắm ý chính.']),
    Q('"Skimming" là?', ['Học thuộc', 'Phân tích từ', 'Đọc lướt nhanh để nắm ý chính', 'Đọc kỹ chi tiết'], 2, 'Skimming = lướt tìm ý chính.', ['Sai — "học thuộc" là memorising, không phải skimming.', 'Sai — "phân tích từ" là word analysis, không phải skimming.', 'Đúng — skimming = đọc lướt nhanh để nắm ý chính.', 'Sai — "đọc kỹ chi tiết" là close/intensive reading, ngược với skimming.']),
    Q('"Scanning" là?', ['Đọc lại', 'Đọc lướt', 'Tìm thông tin cụ thể nhanh', 'Đọc thư giãn'], 2, 'Scanning = tìm chi tiết (số liệu, tên,…).', ['Sai — "đọc lại" là re-reading, không phải scanning.', 'Sai — "đọc lướt" để nắm ý chính là skimming, không phải scanning.', 'Đúng — scanning = tìm thông tin cụ thể nhanh (số liệu, tên).', 'Sai — "đọc thư giãn" là reading for pleasure, không phải scanning.']),
    Q('Khi gặp từ mới, nên?', ['Bỏ qua', 'Học thuộc', 'Tra ngay từ điển', 'Đoán nghĩa qua ngữ cảnh'], 3, 'Đoán theo ngữ cảnh trước khi tra.', ['Sai — "bỏ qua" làm mất nghĩa, không tốt khi gặp từ mới.', 'Sai — "học thuộc" ngay không hiệu quả bằng đoán ngữ cảnh.', 'Sai — tra ngay từ điển làm gián đoạn, nên đoán ngữ cảnh trước.', 'Đúng — nên đoán nghĩa qua ngữ cảnh trước khi tra từ điển.']),
    Q('Câu chủ đề thường nằm ở?', ['Giữa đoạn (inductive - kết luận ở cuối phổ biến hơn)', 'Cuối đoạn (inductive - có nhưng không phổ biến bằng đầu)', 'Đầu đoạn (thông thường)', 'Không cố định'], 2, 'Hay gặp ở đầu đoạn (deductive).', ['Sai — câu chủ đề ít khi nằm giữa đoạn.', 'Sai — cuối đoạn (inductive) có nhưng không phổ biến bằng đầu đoạn.', 'Đúng — câu chủ đề thường ở đầu đoạn (deductive).', 'Sai — không phải "không cố định"; phổ biến nhất là đầu đoạn.']),
    Q('"Inference" trong reading là?', ['Học vẹt', 'Đọc to', 'Dịch nghĩa', 'Suy luận ý ngầm'], 3, 'Inference = suy luận từ ngữ cảnh.', ['Sai — "học vẹt" là rote learning, không phải inference.', 'Sai — "đọc to" là reading aloud, sai nghĩa.', 'Sai — "dịch nghĩa" là translation, không phải suy luận.', 'Đúng — inference = suy luận ý ngầm từ ngữ cảnh.']),
  ]),

  M(31, 'Writing Skills — Essay structure', [
    Q('Một bài essay gồm?', ['Đoạn duy nhất', 'Introduction + Body + Conclusion', 'Chỉ Body', 'Mở + Kết'], 1, '3 phần cơ bản.', ['Sai — essay không chỉ một đoạn duy nhất.', 'Đúng — essay gồm Introduction + Body + Conclusion.', 'Sai — chỉ Body là thiếu mở bài và kết bài.', 'Sai — "Mở + Kết" thiếu phần Body (thân bài).']),
    Q('Topic sentence của đoạn body?', ['Câu chủ đề thể hiện ý chính của đoạn', 'Câu giữa', 'Không cần', 'Câu cuối'], 0, 'Topic sentence dẫn dắt ý cả đoạn.', ['Đúng — topic sentence thể hiện ý chính của đoạn body.', 'Sai — không nhất thiết là câu giữa.', 'Sai — đoạn body cần topic sentence, không phải "không cần".', 'Sai — không cố định là câu cuối; thường là câu đầu đoạn.']),
    Q('"Thesis statement" là?', ['Tiêu đề', 'Đoạn cuối', 'Tên tác giả (author name - không phải luận điểm)', 'Luận điểm trung tâm của bài essay'], 3, 'Thesis = luận đề chính trong introduction.', ['Sai — "tiêu đề" là title, không phải thesis.', 'Sai — "đoạn cuối" là conclusion, không phải thesis.', 'Sai — "tên tác giả" là author name, không liên quan.', 'Đúng — thesis statement = luận điểm trung tâm (trong introduction).']),
    Q('Linking words như "however, therefore, moreover" dùng để?', ['Trang trí', 'Làm dài', 'Vần điệu', 'Nối ý mạch lạc'], 3, 'Connectors giúp logic văn bản.', ['Sai — linking words không chỉ để "trang trí".', 'Sai — không phải để "làm dài" bài.', 'Sai — không phải để tạo "vần điệu".', 'Đúng — linking words nối ý mạch lạc, tạo logic văn bản.']),
    Q('Conclusion cần?', ['Tóm tắt ý chính + restated thesis', 'Thêm ý mới', 'Đặt câu hỏi mở', 'Tả cảnh'], 0, 'Tổng kết + nhắc lại luận điểm.', ['Đúng — conclusion cần tóm tắt ý chính + nhắc lại luận điểm (restated thesis).', 'Sai — không nên thêm ý mới ở kết bài.', 'Sai — đặt câu hỏi mở không phải yêu cầu cốt lõi của conclusion.', 'Sai — "tả cảnh" không phải chức năng của conclusion.']),
    Q('Trong writing, "draft" là?', ['Bản nháp', 'Bản in', 'Bản dịch', 'Bản chính'], 0, 'Draft = bản nháp đầu.', ['Đúng — draft = bản nháp (đầu tiên).', 'Sai — "bản in" là printed copy, không phải draft.', 'Sai — "bản dịch" là translation, sai nghĩa.', 'Sai — "bản chính" là final version, ngược với draft.']),
  ]),

  M(32, 'Listening & Speaking Skills', [
    Q('Khi luyện nghe, nên?', ['Học một câu duy nhất', 'Nghe nhiều lần, đọc transcript', 'Bỏ qua', 'Chỉ đọc'], 1, 'Nghe + transcript hiệu quả.', ['Sai — học một câu duy nhất không cải thiện kỹ năng nghe.', 'Đúng — nghe nhiều lần kết hợp đọc transcript là cách luyện hiệu quả.', 'Sai — "bỏ qua" không giúp luyện nghe.', 'Sai — "chỉ đọc" không rèn được kỹ năng nghe.']),
    Q('Để nói tiếng Anh tốt, cần?', ['Học ngữ pháp duy nhất', 'Im lặng', 'Chỉ đọc nhiều (reading - giúp nhưng không đủ để nói tốt)', 'Luyện phát âm + tự tin nói'], 3, 'Phát âm + nói nhiều.', ['Sai — chỉ học ngữ pháp không đủ để nói tốt.', 'Sai — "im lặng" không cải thiện kỹ năng nói.', 'Sai — chỉ đọc nhiều giúp ích nhưng không đủ để nói tốt.', 'Đúng — luyện phát âm + tự tin nói nhiều là cách cải thiện kỹ năng nói.']),
    Q('"Pronunciation" là?', ['Chính tả', 'Từ vựng', 'Phát âm', 'Ngữ pháp'], 2, 'Pronunciation = sự phát âm.', ['Sai — "chính tả" là spelling, không phải pronunciation.', 'Sai — "từ vựng" là vocabulary, sai nghĩa.', 'Đúng — pronunciation = sự phát âm.', 'Sai — "ngữ pháp" là grammar, sai nghĩa.']),
    Q('"Fluency" là?', ['Sự chậm', 'Sự chính xác', 'Sự nhanh', 'Sự lưu loát'], 3, 'Fluency = nói trôi chảy.', ['Sai — "sự chậm" sai nghĩa, fluency là nói trôi chảy.', 'Sai — "sự chính xác" là accuracy, khác fluency.', 'Sai — "sự nhanh" không hoàn toàn đúng; fluency là trôi chảy.', 'Đúng — fluency = sự lưu loát (nói trôi chảy).']),
    Q('"Intonation" là?', ['Chính tả', 'Trọng âm', 'Ngữ điệu', 'Phát âm'], 2, 'Intonation = lên xuống giọng.', ['Sai — "chính tả" là spelling, không phải intonation.', 'Sai — "trọng âm" là stress, dễ nhầm nhưng khác intonation.', 'Đúng — intonation = ngữ điệu (lên xuống giọng).', 'Sai — "phát âm" là pronunciation, khác intonation.']),
    Q('Khi nói, dùng "fillers" như "um, well, you know" để?', ['Có thời gian suy nghĩ', 'Giữ im lặng', 'Trang trí', 'Tỏ ra thông thái (sai - fillers thực ra cho thấy đang suy nghĩ)'], 0, 'Fillers giúp duy trì lưu loát.', ['Đúng — fillers ("um, well, you know") giúp có thời gian suy nghĩ, duy trì lưu loát.', 'Sai — fillers không phải để giữ im lặng.', 'Sai — fillers không phải để "trang trí".', 'Sai — fillers thực ra cho thấy đang suy nghĩ, không phải tỏ ra thông thái.']),
  ]),

  M(33, 'Grammar Review — All Major Points', [
    Q('Present perfect dấu hiệu?', ['since, for, just, already, yet', 'ago, last', 'now, at the moment (dấu hiệu HTTD, không phải HTHT)', 'tomorrow'], 0, 'Trạng từ đặc trưng.', ['Đúng — since, for, just, already, yet là dấu hiệu hiện tại hoàn thành.', 'Sai — "ago, last" là dấu hiệu quá khứ đơn.', 'Sai — "now, at the moment" là dấu hiệu hiện tại tiếp diễn.', 'Sai — "tomorrow" là dấu hiệu tương lai.']),
    Q('Câu bị động cần?', ['Be + past participle', 'Will + V', 'Be + V-ing', 'Have + V'], 0, 'Công thức bị động.', ['Đúng — bị động: be + past participle (V3).', 'Sai — "Will + V" là tương lai chủ động, không phải bị động.', 'Sai — "Be + V-ing" là tiếp diễn chủ động, không phải bị động.', 'Sai — "Have + V" sai: hiện tại hoàn thành cần have + V3, và đây không phải bị động.']),
    Q('Reported speech: "now" → ?', ['then', 'yesterday', 'tomorrow', 'that day (đổi cho \'today\', không phải \'now\')'], 0, 'Đổi trạng từ.', ['Đúng — trong gián tiếp: now → then.', 'Sai — "yesterday" không phải dạng đổi của "now".', 'Sai — "tomorrow" không phải dạng đổi của "now".', 'Sai — "that day" là dạng đổi của "today", không phải "now".']),
    Q('Type 2 conditional: "If I were…"', ['Were cho they', 'Were dùng cho mọi ngôi', 'Was cho I/he/she', 'Không có were'], 1, 'Were dùng cho tất cả ngôi trong type 2.', ['Sai — không chỉ riêng "they"; were dùng cho mọi ngôi trong Type 2.', 'Đúng — Type 2 dùng "were" cho mọi ngôi (If I were...).', 'Sai — chuẩn Type 2 dùng "were" cho I/he/she, không phải "was".', 'Sai — Type 2 có dùng "were" (với mọi ngôi).']),
    Q('Mệnh đề quan hệ có phẩy là?', ['Mệnh đề trạng ngữ (adverbial clause - khái niệm khác)', 'Hỗn hợp', 'Defining', 'Non-defining'], 3, 'Non-defining có dấu phẩy.', ['Sai — mệnh đề trạng ngữ là khái niệm khác, không liên quan dấu phẩy quan hệ.', 'Sai — "hỗn hợp" không phải tên loại mệnh đề này.', 'Sai — defining clause không có dấu phẩy.', 'Đúng — mệnh đề quan hệ có dấu phẩy là non-defining.']),
    Q('Modal "should" dùng để?', ['Bắt buộc', 'Cấm đoán (mustn\'t dùng cho cấm, không phải should)', 'Khuyên', 'Cho phép'], 2, 'Should = nên (lời khuyên).', ['Sai — bắt buộc là must/have to, không phải should.', 'Sai — cấm đoán là mustn\'t, không phải should.', 'Đúng — should = khuyên (nên làm gì).', 'Sai — cho phép là may/can, không phải should.']),
  ]),

  M(34, 'Practice Test 1 — End of Year', [
    Q('"She ___ in Hanoi since 2010."', ['lived (QKĐ - không hợp \'since 2010\' tới hiện tại)', 'lives (HTĐ - không diễn tả khoảng kéo dài)', 'has lived', 'is living'], 2, 'Since → present perfect.', ['Sai — "lived" quá khứ, không hợp "since 2010" kéo dài tới hiện tại.', 'Sai — "lives" hiện tại đơn, không diễn tả khoảng kéo dài.', 'Đúng — "since" → hiện tại hoàn thành has lived.', 'Sai — "is living" tiếp diễn, không nhấn khoảng tích luỹ từ 2010.']),
    Q('"The thief ___ by the police yesterday."', ['caught', 'was caught', 'catches', 'is caught'], 1, 'Quá khứ bị động.', ['Sai — "caught" thiếu trợ động từ was, sai dạng bị động.', 'Đúng — quá khứ bị động: was + V3 = was caught (yesterday).', 'Sai — "catches" hiện tại đơn chủ động, sai thì và dạng.', 'Sai — "is caught" hiện tại, không hợp "yesterday".']),
    Q('"If I ___ you, I would study harder."', ['will be', 'am (HTĐ - không phải điều kiện không thực)', 'was (văn nói được, nhưng chuẩn Type 2 là were)', 'were'], 3, 'Type 2: were với mọi ngôi.', ['Sai — "will be" không dùng trong mệnh đề if Type 2.', 'Sai — "am" hiện tại đơn, không phải điều kiện không thực.', 'Sai — "was" văn nói được, nhưng chuẩn Type 2 dùng "were".', 'Đúng — Type 2: were với mọi ngôi (If I were you).']),
    Q('"He asked me what time ___."', ['was it', 'it is (HTĐ - sai vì câu chính ở quá khứ)', 'is it (đảo ngữ - sai cấu trúc câu gián tiếp)', 'it was'], 3, 'Indirect question: WH + S + V.', ['Sai — "was it" đảo ngữ, sai cấu trúc câu gián tiếp.', 'Sai — "it is" hiện tại, sai vì câu chính ở quá khứ (asked).', 'Sai — "is it" đảo ngữ, sai cấu trúc gián tiếp.', 'Đúng — câu hỏi gián tiếp: WH + S + V = what time it was.']),
    Q('"The book ___ I read was great."', ['where (nơi chốn - không phù hợp với \'book\')', 'that/which', 'who (người - book là vật)', 'whose (sở hữu - không phù hợp tân ngữ vật)'], 1, 'Vật → that/which.', ['Sai — "where" chỉ nơi chốn, không hợp với "book" (vật).', 'Đúng — vật → that/which (the book that/which I read).', 'Sai — "who" chỉ người; book là vật.', 'Sai — "whose" chỉ sở hữu, không hợp tân ngữ chỉ vật.']),
    Q('"___ pollute the environment is wrong."', ['To', 'In (giới từ - không tạo được chủ ngữ động từ nguyên)', 'For (giới từ - tạo cụm V-ing, không V nguyên)', 'At (giới từ - không hợp với động từ nguyên)'], 0, 'To + V nguyên ở đầu câu = chủ ngữ.', ['Đúng — To + V nguyên ở đầu câu làm chủ ngữ (To pollute... is wrong).', 'Sai — "In" là giới từ, không tạo được chủ ngữ động từ nguyên.', 'Sai — "For" tạo cụm khác, không phải chủ ngữ V nguyên.', 'Sai — "At" là giới từ, không hợp với động từ nguyên làm chủ ngữ.']),
  ]),

  M(35, 'Practice Test 2 — Final Review', [
    Q('"Where ___ you born?"', ['was (QKĐ ngôi 1/3 - \'you\' luôn dùng were)', 'were', 'are (HTĐ - không phải quá khứ \'born\')', 'is (HTĐ ngôi 3 - không hợp \'you\')'], 1, 'Bị động quá khứ + you → were.', ['Sai — "was" dùng cho I/he/she/it; "you" luôn dùng "were".', 'Đúng — bị động quá khứ + you → were (Where were you born?).', 'Sai — "are" hiện tại, không phải quá khứ "born".', 'Sai — "is" hiện tại ngôi 3, không hợp với "you".']),
    Q('"I wish I ___ more time."', ['will have', 'has (HTĐ ngôi 3 - sau wish cần quá khứ)', 'have (HTĐ - sau wish cần quá khứ đơn)', 'had'], 3, 'Wish + past simple = ước hiện tại.', ['Sai — "will have" sai: sau wish (hiện tại) dùng quá khứ đơn.', 'Sai — "has" hiện tại ngôi 3, sau wish cần quá khứ.', 'Sai — "have" hiện tại, sau wish cần quá khứ đơn.', 'Đúng — wish + past simple = ước ở hiện tại (I wish I had more time).']),
    Q('"Tom is ___ student in his class."', ['the most intelligent', 'most intelligent', 'intelligent', 'more intelligent'], 0, 'So sánh nhất với adj dài: the most + adj.', ['Đúng — so sánh nhất adj dài: the most + adj = the most intelligent.', 'Sai — "most intelligent" thiếu mạo từ "the".', 'Sai — "intelligent" nguyên cấp, không phải so sánh nhất.', 'Sai — "more intelligent" là so sánh hơn, không hợp "in his class" (nhất).']),
    Q('"He ___ his homework before his mother came home."', ['did (QKĐ - không thể hiện trước hành động \'came\')', 'had done', 'was doing', 'has done'], 1, 'Past perfect cho hành động trước past simple.', ['Sai — "did" quá khứ đơn, không thể hiện hành động xảy ra trước "came".', 'Đúng — quá khứ hoàn thành cho hành động trước past simple (had done before came).', 'Sai — "was doing" tiếp diễn, không nhấn hoàn tất trước "came".', 'Sai — "has done" hiện tại hoàn thành, không hợp ngữ cảnh quá khứ.']),
    Q('"I look forward to ___ you soon."', ['saw (QKĐ - không hợp sau \'to\' của cụm cố định)', 'seeing', 'to see', 'see (V nguyên - look forward to + V-ing)'], 1, 'Look forward to + V-ing.', ['Sai — "saw" quá khứ, không hợp sau "to" của cụm cố định.', 'Đúng — look forward to + V-ing = look forward to seeing.', 'Sai — "to see" sai: ở đây "to" là giới từ, theo sau là V-ing.', 'Sai — "see" V nguyên: look forward to + V-ing, không V nguyên.']),
    Q('Synonyms of "happy"?', ['sick, weak', 'tired, bored', 'glad, joyful, cheerful', 'sad, angry'], 2, 'Các từ đồng nghĩa của happy.', ['Sai — "sick, weak" không phải đồng nghĩa với happy.', 'Sai — "tired, bored" không phải đồng nghĩa với happy.', 'Đúng — glad, joyful, cheerful đều đồng nghĩa với happy.', 'Sai — "sad, angry" trái nghĩa với happy.']),
  ]),
  M(36, 'Closing Chapter — Grade 10 English and the Road Ahead', [
    Q('Which grammar areas were the backbone of Grade 10 English?', ['Only articles and plurals', 'Tenses, conditionals types 1 and 2, passives, reported speech, modals, relative clauses', 'Only phrasal verbs', 'Only spelling rules'], 1, 'Grade 10 covered tenses, conditionals 1 and 2, passives, reported speech, modals and relative clauses.', ['No — articles and plurals are covered much earlier.', 'Correct — these six areas form the Grade 10 grammar core.', 'No — phrasal verbs are only one part of vocabulary work.', 'No — spelling is not a separate grammar strand at this level.']),
    Q('Which conditional structures are introduced in Grade 11 rather than Grade 10?', ['Type 3 and mixed conditionals', 'Type 1 only', 'Type 2 only', 'Zero conditional only'], 0, 'Grade 11 adds conditional type 3 and mixed conditionals on top of types 1 and 2.', ['Correct — type 3 and mixed conditionals are the new ground in Grade 11.', 'No — type 1 was already mastered in Grade 10.', 'No — type 2 was also part of the Grade 10 syllabus.', 'No — the zero conditional is the most basic pattern, learned earlier.']),
    Q('Which structures does Grade 11 add for more academic writing?', ['Simple present and there is / there are', 'Basic greetings and introductions', 'Numbers and dates', 'Inversion, cleft sentences and emphasis structures'], 3, 'Inversion, cleft sentences and emphasis structures are added for academic writing in Grade 11.', ['No — these are elementary patterns, not academic ones.', 'No — greetings belong to beginner level.', 'No — numbers and dates are basic vocabulary.', 'Correct — inversion, cleft sentences and emphasis raise the register of writing.']),
    Q('Which skill is described as a key one for the national exam?', ['Handwriting neatness', 'Word forms: noun, verb, adjective and adverb transformations', 'Reciting the alphabet', 'Copying texts by hand'], 1, 'Word form transformation is highlighted as a key national exam skill.', ['No — the exam is not handwriting based.', 'Correct — word form transformation appears regularly in the national exam.', 'No — that is a beginner activity.', 'No — copying does not build exam skills.']),
    Q('What does the summer plan suggest for weeks 3 and 4?', ['Stop studying completely', 'Only revise the alphabet', 'Expand vocabulary with about 10 new words a day using Anki or Quizlet', 'Translate the whole textbook into Vietnamese'], 2, 'Weeks 3 and 4 focus on learning roughly ten new words a day with spaced repetition apps.', ['No — the plan asks for small daily steps, not a full stop.', 'No — the alphabet is not part of the plan.', 'Correct — about ten new words a day with Anki or Quizlet.', 'No — full translation is not part of the suggested plan.']),
    Q('Why is English described as "a skill, not a subject"?', ['Because it is never tested', 'Because it improves the more you use it, so steady practice beats cramming', 'Because grammar does not matter', 'Because only native speakers can learn it'], 1, 'English improves through regular use, so consistent small steps beat a last minute sprint.', ['No — English is tested in school and in the national exam.', 'Correct — regular use builds the skill; cramming does not.', 'No — grammar remains an important part of accuracy.', 'No — learners at every level can improve with practice.']),
  ]),
];

export const H10TA_SCENARIOS = indexBy(H10TA_WEEKS);
